    [2518] = "Жрица А'моора из дарнасского храма Луны хочет, чтобы вы принесли ей серебряные паутинные железы леди Сатры.",
    [2519] = "Сестра Аквинна хочет, чтобы вы поговорили со жрицей А'моорой из Храма Луны.",
