    [2521] = "Если в своем путешествии по Выжженным землям вы найдете безупречную сферу из дренейского аметиста, отнесите ее Кум'ише Коллекционеру. Будьте внимательны – этот камень – один из самых редких кристаллов во всем Азероте. Любое существо в этих землях может владеть безупречной сферой из дренейского аметиста. Вы будете вознаграждены за каждую безупречную сферу из дренейского аметиста, которую доставите Кум-ише.",
    [2522] = "Найдите безупречную сферу из дренейского аметиста и верните ее Кум'ише Коллекционеру.",
