    [2581] = "Принесите три челюсти гиены, два обожженных легких вепря и одну клешню скорпока магу Крови Дразиалу.",
    [2582] = "Принесите три челюсти гиены, два обожженных легких вепря и одну клешню скорпока магу Крови Дразиалу.",
    [2583] = "Принесите три обожженных легких вепря, две клешни скорпока и один мозг василиска волшебнице крови Дразиале.",
    [2584] = "Принесите три обожженных легких вепря, две клешни скорпока и один мозг василиска магу Крови Дразиалу.",
    [2585] = "Принесите три клешни скорпока, две единицы потрохов стервятника и одно обожженное легкое вепря волшебнице крови Дразиале.",
