    [3566] = "Убейте Латорика Черного и Обсидиона и принесите голову Латорика и сердце Обсидиона Ториусу в Стальгорн.",
    [3568] = "Наполните все 4 пустых фиала из приливных заводей в руинах Эльдарата и возвращайтесь к химику Карабосу.",
    [3569] = "Дайте эликсир Карабоса Терсе Песне Ветра в Подгороде.",
    [3601] = "Обыщите Талассийское поселение и найдите компас, прицел, плюшевого цыпленка и центробежный растягиватель Ким'джаеля. Верните все это Ким'джаелю в Азшару.",
    [3602] = "Найдите в южной Азшаре двадцать кристаллов азшарита. Вы можете использовать Гончих Скверны, которые помогут вам \"вынюхивать\" местонахождение хорошо сокрытых залежей. Когда задача будет завершена, возвращайтесь к Лорамусу Многоногу.",
    [3621] = "Отнести груз Гальвану Древнему в Тернистую долину.",
    [3625] = "Подождите, пока Гальван закончит отковывать оружие.",
    [3626] = "Вернитесь к Павшему герою Орды.",
    [3627] = "Убейте Грола Разрушителя, леди Севину и верховного мага Аллистария. С их трупов заберите Амулет Грола, Амулет Севины и Амулет Аллистария. Помните о том, что нужно использовать зачарованное азшаритовое оружие, отравленное Скверной, чтобы ослабить троицу! Их нельзя убить иначе – но используйте оружие разумно...",
    [3628] = "Уничтожьте Разелиха Осквернителя и вернитесь к Павшему герою Орды с Отрубленным Рогом Осквернителя. Вам также понадобится вернуть Оберег Осквернителя, чтобы Павший герой мог уничтожить его, дабы оберег не попал к тому, кто использует его во зло.",
    [3629] = "Если вы хотите узнать больше о гоблинском инженерном деле, отнесите справочник по инженерным дисциплинам Никсу Шепружину в Прибамбасск.",
    [3630] = "Если вы хотите узнать больше о гномском инженерном деле, отнесите справочник по инженерным дисциплинам мехмастеру Замыкальцу в Стальгорн.",
    [3631] = "Поговорите в Кабестане со Страхадом Фарсаном.",
    [3632] = "Возьмите Справочник по инженерным дисциплинам и отнесите его мехмастеру Замыкальцу в Стальгорн.",
    [3633] = "Если вы хотите узнать о гоблинском инженерном деле, отнесите cправочник по инженерным дисциплинам Никсу Шепружину в Прибамбасск.",
    [3634] = "Если хотите узнать побольше о гномском инженерном деле, возьмите справочник по инженерным дисциплинам и отнесите мехмастеру Замыкальцу в Стальгорн.",
    [3635] = "Если вы хотите узнать побольше о гномском инженерном деле, возьмите справочник по инженерным дисциплинам и отнесите его Карлсу Пропеллерзу в Пиратскую бухту.",
    [3636] = "Убейте Амненнара Хладовея на Курганах Иглошкурых.",
    [3637] = "Если вы хотите узнать побольше о гномском инженерном деле, возьмите справочник по инженерным дисциплинам и отнесите его Карлсу Пропеллерзу в Пиратскую бухту.",
    [3638] = "Если вы согласны заниматься гоблинским инженерным делом, щелкните правой кнопкой мыши по Договору о неразглашении и еще раз обратитесь к Никсу Шепружину в Прибамбасске.",
    [3639] = "Принесите 20 больших железных бомб, 20 шашек плотного динамита и 5 взрывоопасных овец Никсу Шепружину в Прибамбасск.",
    [3640] = "Щелкните правой кнопкой мыши по Договору о неразглашении и еще раз обратитесь к мехмастеру Замыкальцу в Стальгорне.",
    [3641] = "Принесите 6 мифриловых трубок, точный прицел и 2 усовершенствованных манекена-мишени мехмастеру Замыкальцу в Стальгорн.",
    [3642] = "Если вы согласны заниматься гномским инженерным делом, щелкните правой кнопкой мыши по Договору о неразглашении и еще раз обратитесь к Карлсу Пропеллерзу в Пиратской бухте.",
    [3643] = "Принесите 6 мифриловых трубок, точный прицел и 2 усовершенствованных манекена-мишени Карлсу Пропеллерзу в Пиратскую бухту.",
    [3661] = "Собрерите во Внутренних землях 15 перьев диких совухов и отнесите их Эреласу Янтарному Небу в деревню Рут'теран.",
    [3681] = "Разыщите в Штормграде Даториана Ралла и поговорите с ним.",
    [3701] = "Пойдите в руины Тауриссана в Пылающих степях и добудьте информацию из таурисанских реликвий. Вернитесь к королевскому историку Аркессону.",
    [3702] = "Узнайте от королевского историка Аркессона историю Тауриссана.",
    [3741] = "Найдите ожерелье Хилари и верните его Хилари в Приозерье.",
    [3761] = "Принесите 20 образцов земли из Кратера Ун'Горо Геду на Вершину Старейшин Громового Утеса.",
    [3762] = "Поговорите с верховным друидом Хамуулом Руническим Тотемом в Громовом Утесе.",
    [3763] = "Поговорите с верховным друидом Фэндралом Оленьим Шлемом в Дарнассе.",
    [3764] = "Принесите 20 образцов земли из кратера Ун'Горо Дженалю в дарнасский анклав Кенария.",
    [3765] = "Отправляйтесь в Аубердин к Гершалу Шепоту Ночи.",
    [3781] = "Отнесите расписку верховного друида в получении семян Матренгилу Медвежьей Лапе в дарнасский анклав Кенария.",
    [3782] = "Отнесите расписку в получении семян Башане Руническому Тотему в Громовой Утес.",
    [3783] = "Соберите 10 толстых кусков меха йети для Юми Румпельшникер из Круговзора.",
    [3784] = "Поговорите с верховным друидом Хамуулом Руническим Тотемом на Уступе Древних Громового Утеса.",
    [3785] = "При помощи сумы вечного цветения, пакетика семян Тарлендриса и двух порций земли Ун'Горо попытайтесь прорастить рассветницу. Принесите 10 рассветниц Матренгилу Медвежьей Лапе в Дарнасс.",
    [3786] = "При помощи сумы вечного цветения, пакетика семян Тарлендриса и двух порций земли Ун'Горо попытайтесь прорастить рассветницу. Принесите 10 рассветниц Башане Руническому Тотему в Громовой Утес.",
    [3787] = "Поговорите с Квинтисом Ночным Костром в Крепости Оперенной Луны.",
    [3788] = "Поговорите с друидом по имени Квинтис Ночной Костер в Крепости Оперенной Луны.",
    [3789] = "Поговорите с верховным друидом Фэндралом Оленьим Шлемом в Дарнассе.",
    [3790] = "Поговорите с верховным друидом Фэндралом Оленьим Шлемом в Дарнассе.",
    [3791] = "Принесите 10 рассветниц друиду по имени Квинтис Ночной Костер в Крепости Оперенной Луны.",
    [3801] = "Чтобы получить ключ от города, поговорите с Франклорном Искусником.",
    [3802] = "Убейте Точеня Темностроя и добудьте великий молот, Железный Друг. Отнесите Железного Друга в святилище Тауриссана и вложите его в руки статуи Франклорна Искусника.",
    [3821] = "Отправляйтесь в Пылающие степи и выясните, что сталось с Ша'ни Гордым Клыком.",
    [3822] = "Заберите ноздревое кольцо Ша'ни у Кром'Грула и верните его Тал'траку из Каргата. Обыщите различные пещеры и рудники скалы Молота Ужаса.",
    [3823] = "Убейте 15 огров-магов, 7 огров и 7 громил из клана Огненного Чрева. По выполнении задания вернитесь к Орелиусу.",
    [3824] = "Найдите Гор'теша на западе от скалы Молота Ужаса. Убейте Гор'теша и отнесите его голову Орелиусу в Пылающие степи.",
    [3825] = "Отнесите голову Гор'теша на вершину скалы Молота Ужаса. Поищите кучу рыхлой земли и воткните в нее пику.",
    [3841] = "Поговорите с Квентином в Тысяче Игл.",
    [3842] = "Принесите 2 |4малый эликсир:малых эликсира:малых эликсиров; стойкости Квентину в Тысячу Игл.",
    [3843] = "Отнесите хрупкое яйцо летучего хамелеона во Внутренние земли и поговорите с Агнаром Зверопасом. У вас есть на это всего 1 час. В противном случае детеныш в яйце умрет.",
    [3844] = "Осмотритесь и попытайтесь выяснить, кому мог бы принадлежать разбитый плот.",
    [3845] = "Изучите найденное в сумке и верните владельцу.",
    [3861] = "Найдите немного цыплячьего корма и вернитесь к вашей курочке-подружке. Когда найдете ее, /поклонитесь ей прежде, чем накормить ее специальным цыплячьим кормом.",
    [3881] = "Принесите ящик с провизией и исследовательское оборудование Виллидену Маршалу в Кратер Ун'Горо.",
    [3882] = "Принесите 8 костей динозавра Искру Пустокопу в Кратер Ун'Горо.",
    [3883] = "Воспользуйтесь фиалом для образцов, чтобы взять образец материала стены улья из одного из инкубаторов Гориши в Кратере Ун'Горо. Ищите в ульях комнаты со свисающими гроздьями личинок. Принесите образец материала стены улья Холании Маршал в Кратер Ун'Горо.",
    [3884] = "Верните дневник Виллидену Маршалу, который находится где-то в Кратере Ун'Горо.",
    [3901] = "Убейте 12 скелетов-костетрясов, а затем вернитесь к жрецу Тьмы Сарвису в Могильник.",
    [3902] = "Обыщите Могильник и его окрестности и найдите 6 ящиков с добычей и передайте их стражу смерти Салтену.",
    [3903] = "Поговорите с Милли Осворт.",
    [3904] = "Принесите 8 корзин с виноградом Милли Осворт в Аббатство Североземья.",
    [3905] = "Отнесите уведомление о поставке винограда брату Нилзу в Аббатство Североземья.",
    [3906] = "Отправьтесь в карьер у Черной горы и уничтожьте Подчинителя Пирона. По выполнению вернитесь к Громосерду.",
    [3907] = "Ступайте в глубины Черной горы и выследите лорда Опалителя. Убейте его и принесите Громосерду все, что может дать какую-то информацию.",
    [3908] = "Отнесите меч Линкена Донове Снегоноре.",
    [3909] = "Найдите Грегана Пивоплюя на севере Фераласа. Выясните у него, как получить эликсир Видере, и вернитесь к Донове Снегоноре.",
    [3912] = "Отправляйтесь на кладбище на окраине Прибамбасска и выпейте там эликсир Видере. Далее, следуя инструкциям Доновы, найдите Гаэриана.",
    [3913] = "Воскресните, найдите могильный камень, о котором говорил Гаэриан.",
    [3914] = "Доставьте превосходный меч Линкена Линкену в Кратер Ун'Горо.",
    [3921] = "Отнесите сломанный самофланж Венаки Бенике.",
    [3922] = "Принесите 15 металлических заготовок для деталей Венаки Бенике в Степи.",
    [3923] = "Отнесите разбитый и сломанный самофланж Рилли Грязегобу в Оргриммар.",
    [3924] = "Отнесите руководство по самофланжу Рилли Грязегобу в Оргриммар.",
    [3941] = "Найдите Джей Ди Колли в Укрытии Маршалла.",
    [3942] = "Найдите Эридану Грусть Ветра на юге Оскверненного леса.",
    [3961] = "Отнесите серебряный тотем Аквамонтоса Линкену в Укрытие Маршалла.",
    [3962] = "Отправляйтесь к Вулкану Огненного Венца, к югу от Укрытия Маршалла. Найдите Яропламеня и разрушьте его защитную ауру с помощью тотема. Когда дух будет сражен, заберите из пещеры Золотое пламя.",
    [3981] = "Найдите командира Гор'шака в Глубинах Черной горы. Судя по рисунку в записке, искать следует в темнице где-то вроде того.",
    [3982] = "Защитите Горшака.",
    [4001] = "Поговорите с дворфом по имени Каран Могучий Молот и соберите информацию о похищении принцессы Мойры Бронзобород. Передайте информацию Траллу в Оргриммар. Карана держат в темнице напротив.",
    [4002] = "Поговорите с Траллом.",
    [4003] = "Убейте императора Даграна Тауриссана и освободите принцессу Мойру Бронзобород от его черного заклятия.",
    [4004] = "Вернитесь к Траллу.",
    [4005] = "Отнесите книгу Аквора, серебристые когти и сердце Железнолесья в Танарис. Воспользуйтесь книгой для призыва Аквамонтоса. По получении тотема, отнести его Джей Ди Колли в Укрытие Маршалла.",
    [4021] = "Принесите кусок знамени Кром'зара Регтару Вратам Смерти. Его можно найти на западе от Перекрестка.",
    [4022] = "Покажите Цирусу Раскаивателю сброшенную кожу черного дракона, полученную от Веларока Ветрореза.",
    [4023] = "Покажите Цирусу Раскаивателю доказательство своих деяний. Возникает чувство, что Цирус заранее сомневается в ваших качествах.",
    [4024] = "Отправьтесь в глубины Черной горы и убейте Бейл'Гора. Известно лишь то, что великан живет в глубинах. Воспользуйтесь измененной сброшенной шкурой черного дракона и возьмите из останков Бейл'Гора сущность Огня. Отнесите пойманную сущность Огня Цирусу Раскаивателю.",
    [4061] = "Отправляйтесь в Пылающие степи и соберите 10 осколков элементалей для верховной жрицы Теодоры Мальвадании. Теодора упоминала, что осколки можно найти у элементалей и големов.",
    [4062] = "Отнесите образец осколка элементаля Лотвилю Вериатусу. Теодора упоминала, что его лагерь находится на востоке.",
    [4063] = "Найдите и убейте повелителя големов Аргелмаха. Принесите его голову Лотвилу. Также соберите 10 невредимых ядер стихий с беспощадных големов и созданий-завоевателей, охраняющих Аргелмаха. Информация передана посредством телепатии.",
    [4081] = "Отправляйтесь в Глубины Черной горы и уничтожьте подлых агрессоров! По приказу полководца Клинозуба уничтожьте 15 охранников, 10 надсмотрщиков и 5 пехотинцев из клана Ярости Горна. Вернитесь сразу по выполнении задания.",
    [4082] = "Отправляйтесь в Глубины Черной горы и уничтожьте подлых агрессоров! По приказу полководца Клинозуба уничтожьте 10 медиков, 10 солдат и 10 офицеров из клана Ярости Горна. Вернитесь сразу по выполнении задания.",
    [4084] = "Добудьте 11 серебристых когтей и 1 сердце Железнолесья для Эриданы Грусти Ветра.",
    [4101] = "Принесите 15 кровавых янтарей Аратандис Серебряному Небу в Оскверненный лес.",
    [4102] = "Принесите 15 кровавых янтарей Майбессе Речному Ветру в Оскверненный лес.",
    [4120] = "Убейте 12 гризли злобных когтей и 12 опустошителей-сквернолапов в Оскверненном лесу по просьбе Тало Тернового Копыта из лагеря Мохаче.",
    [4121] = "Отконвоируйте пленника, Грарка Лорктуба, через Пылающие степи и Черную гору к Тлеющему ущелью. Лекслорт что-то говорил насчет того, что по другую сторону будут ждать его ребята, которые уведут Грарка в тюрьму. Также отдайте Лекслорту ториевые оковы.",
    [4122] = "Отправьтесь в Пылающие степи и найдите Грарка Лоркруба. Лекслорт упоминал, что в последний раз предателя видели в крепости Черной горы. По обнаружении Грарка Лоркруба закуйте его в ториевые оковы и затем доставьте его от Черной горы к Тлеющему ущелью, Лекслорт и его подчиненные займутся допросом преступника.",
    [4123] = "Принесите сердце горы Максворту Суперблеску в Пылающие степи.",
    [4124] = "Поговорите с Гинро Пылающим Очагом в Крепости Оперенной Луны.",
    [4125] = "Отыщите лодку курьера, которая должна находиться где-то на побережье Фераласа.",
    [4126] = "Найдите украденный рецепт громоварского и верните его Рагнару Громовару в Каранос.",
    [4127] = "Вернитесь в Крепость Оперенной Луны и покажите Гинро Пылающему Очагу выброшенный нож, который вы нашли.",
    [4128] = "Переговорите с Рагнаром Громоваром.",
    [4129] = "Отнесите выброшенный нож к друиду по имени Квинтис Ночной Костер в Крепости Оперенной Луны.",
    [4130] = "Поговорите с Гинро Пылающим Очагом в Крепости Оперенной Луны.",
    [4131] = "Обыщите лагеря Древолапов в южном Фераласе в поисках вещей курьера либо самого курьера.",
    [4132] = "Отправляйтесь в Глубины Черной горы и убейте генерала Кузню Гнева. Вернитесь к полководцу Клинозубу по выполнении задания.",
    [4133] = "Переговорите с тенемагом Вивиан Лаграв в Каргате.",
    [4134] = "Принесите рецепт громоварского светлого Вивиан Лягроб в Каргат.",
    [4135] = "Продолжайте поиски Раскала (или его останков) в Гудящей Бездне. Согласно записке, Гудящая Бездна находится к югу от лагерей стаи Древолапов.",
