    [4201] = "Принесите 4 листа крови Грома, 10 огромных серебряных слитков и наполненный сосуд Нагмары госпоже Нагмаре в Глубины Черной горы.",
    [4223] = "Поговорите с маршалом Максвеллом в Пылающих степях.",
    [4224] = "Поговорите с Джоном-Оборванцем и узнайте о судьбе маршала Виндзора. По выполнении задания вернитесь к маршалу Максвеллу. Кажется, маршал Максвелл говорил, что Джона следует искать в пещере на севере.",
    [4241] = "Отправляйтесь на Черную гору на северо-западе и войдите в ее глубины. Узнайте, что сталось с маршалом Виндзором. Кажется, Джон-Оборванец говорил о том, что Виндзора утащили в темницу.",
    [4242] = "Сообщите маршалу Максвеллу плохие новости.",
