    [4581] = "Отнесите записку Шиндрелл Кайнету Штилю в Лесную Песнь.",
    [4621] = "Убейте командира флота Морского Рога и барона Ревилгаза из Пиратской бухты, а потом возвращайтесь к командиру флота Фираллону на борту \"Багрового Паруса\" неподалеку от побережья Тернистой долины.",
