    [4642] = "Принесите образец перемешанной слизи химику Барабосу в Подгород.",
    [4681] = "Извлеките останки морской черепахи из скелета морской черепахи, лежащего в воде к западу от Аубердина, а затем поговорите с Гвеннид Блай'Леггонд в Аубердине.",
