    [4726] = "Принесите 8 сущностей детенышей драконов и Драко-инкарцинатор 900 Тинки Кипеллер в Пламенеющий Стяг в Пылающих степях.",
    [4727] = "Отнесите останки морской черепахи Гвеннид Блай'Леггонд в Аубердин.",
    [4728] = "Отнесите кости морской твари Гвеннид Блай'Леггонд в Аубердин.",
    [4729] = "Отправьтесь на пик Черной горы и отыщите там щенков воргов легиона Кровавого Топора. Посадите маленьких тварей в клетку и отнесите Киблеру.",
    [4730] = "Отнесите кости морской твари Гвеннид Блай'Леггонд в Аубердин.",
    [4731] = "Отнесите ящик со странными пометками Гвеннид Блай'Леггонд в Аубердин.",
    [4732] = "Отнесите останки морской черепахи Гвеннид Блай'Леггонд в Аубердин.",
    [4733] = "Отнесите кости морской твари Гвеннид Блай'Леггонд в Аубердин.",
    [4734] = "Испытайте прототип яйцехладоскопа на одном из яиц в Гнездовье.",
    [4735] = "Принесите 8 драконьих яиц и устройство-коллекционер Тинки Кипеллер в Пламенеющий Стяг в Пылающих степях.",
    [4736] = "Поговорите с Менарой Расщепительницей Бездны в Степях.",
    [4737] = "Поговорите с Менарой Расщепительницей Бездны в Степях.",
    [4738] = "Поговорите с Менарой Расщепительницей Бездны в Степях.",
    [4739] = "Поговорите с Менарой Расщепительницей Бездны в Степях.",
    [4740] = "Найдите и убейте мурлока, известного как Глубомрак. Предполагается, что это существо охраняет и защищает хижины мурлоков в поселении к югу от Аубердина, у воды. О смерти Глубомрака доложите часовому Глинде Нал'Шии в Аубердине.",
    [4741] = "Убейте для Трулла Баловня Судьбы из Оскверненного леса 13 лунных совухов.",
    [4742] = "Найдите самоцвет Тлеющего Терновника, самоцвет Черной Вершины и самоцвет Кровавого Топора. Верните их Ваелану вместе с простой печатью Вознесения. Камни могут быть у трех генералов: у воеводы Вуна из клана Тлеющего Терновника, у вождя Омокка из клана Черной Вершины и у повелителя Змейталака из клана Кровавого Топора.",
    [4743] = "Идите в Драконьи топи в Пылевых топях. Найдите Огнебора и бейте его, не жалея, чтобы сломить его волю. Как только воля великого зверя ослабнет, надо немедленно положить перед ним заготовку печати Вознесения и воспользоваться сферой Энергии дракона, чтобы подчинить себе его разум и направить его пламя на заготовку.",
    [4761] = "Поговорите с Тандрисом Ветропрядом в Аубердине.",
    [4762] = "Отправляйтесь на север от Аубердина, к первому водопаду вверх по реке Скалистой, и там возьмите пробу. С пробой воды Скалистой реки возвращайтесь в Аубердин к Тандрису Ветропряду.",
    [4763] = "Наполните пустую чашу очищения из лунного колодца Аубердина. Соберите образцы фруктов, орехов и зерна в расположенных на севере лагерях фурболгов. Смешайте все в чаше и поместите ее возле ближайшего к реке Скалистой большого костра в северном лагере, вызвав таким образом сатира. Снимите с него талисман порчи и принесите его Тандрису Ветропряду в Аубердин.",
    [4764] = "Принесите пряжку Роковой оснастки Майре Светлое Крыло в Пылающие степи.",
    [4765] = "Отнесите ящик Риджвелла Ремингтону Риджвеллу в Штормград.",
    [4766] = "Поговорите с Майрой в Пылающих степях.",
    [4767] = "Соберите в Скальном гнездовье 10 яиц виверн и отнесите их Элу на Заставу Вольного Ветра.",
    [4768] = "Принесите табличку Темного Камня тенемагу Вивиан Лаграв в Каргат.",
    [4769] = "Переговорите с темным магом Вивианой Лягроб.",
    [4770] = "Выведите Паоку Ходячую Гору из Скального гнездовья, а потом поговорите с Мотегой Огненной Гривой на заставе Белого Плеса.",
    [4771] = "Отнесите \"Рассветный гамбит\" в Демонстрационную комнату в Некроситете. Уничтожьте Вектуса и возвращайтесь к Бетине Биггльцинк.",
    [4781] = "Отнесите слиток золота Зиску Ладноскрою в Тернистую долину.",
    [4782] = "Возвращайтесь к Менаре Расщепительнице Бездны в Степи.",
    [4783] = "Принесите 10 фиалов крови сатира из племени Ярой Ненависти и 1 простой камень Преисподней в Степи, Менаре Менара Расщепительнице Бездны.",
    [4784] = "Принесите Менаре Расщепительнице Бездны в Степи нить из чистого золота, 2 тлеющих угля и осколок души.",
    [4786] = "Дождитесь, пока Менара Расщепительница Бездны закончит работу над вашим одеянием, и еще раз поговорите с ней.",
    [4787] = "Принесите древнее яйцо Йе'кинье в Танарис.",
    [4788] = "Принесите пятую и шестую таблички Мошару геологу Железному Башмаку в Танарисе.",
    [4808] = "Отнесите письмо Тинки Фелноку Сталлисту.",
    [4809] = "Принесите 8 безупречных рогов стылодыха Фелноку Сталлисту.",
    [4810] = "Отнесите ящик Фелнока Тинки Кипеллер в Пылающие степи.",
    [4811] = "Направляйтесь на восток от Аубердина и поищите большой красный кристалл в горной гряде на востоке Темного Берега. Вернитесь с докладом к часовому Глинде Нал'Шие в Аубердин.",
    [4812] = "Наполните пустую колбу для воды в лунном колодце Аубердина, а затем исследуйте красный кристалл, находящийся в горной гряде на востоке Темного Берега.",
    [4813] = "Доложите о результатах ваших изысканий часовому Глинде Нал'Шие в Аубердине.",
    [4821] = "Принесите неизвестное яйцо Хагару Грозовому Копыту на Заставу Вольного Ветра.",
    [4841] = "Убейте 12 разведчиков, 10 пастухов и 6 ветроловок из племени Галак, после чего вернитесь к дозорному утесов Долгорогу на Заставу Вольного Ветра.",
    [4842] = "Последуйте указаниям Доновы Снегоноры, а затем вернитесь к ней.",
    [4861] = "Найдите разоренный лагерь Джерона Гранильщика и его припасы на юге Зимних Ключей.",
    [4862] = "Отправьтесь на пик Черной горы и принесите Киблеру 15 яиц скального паука. Судя по всему, яйца надо искать недалеко от пауков.",
    [4863] = "Найдите опрокинутый фургон Джерона Гранильщика.",
    [4864] = "Подберите припасы Джерона из снега, и найдите дикого совуха, похитившего амулет, о котором говорил Джерон. Принесите припасы и ожерелье миних перьев Джерону Гранильщику в его дом в Зимних Ключах.",
    [4865] = "Расскажите о найденном Мотеге Огненной Гриве.",
    [4866] = "Найдите в самом сердце пика Черной горы мать Дымную Паутину. Сражайтесь с ней, пока она не введет вам свой яд. Скорее всего ее также придется убить. Когда яд будет в вас, вернитесь к Джону-Оборванцу, чтобы он смог добыть яд.",
    [4867] = "Прочитайте записку Вароша. Принесите Варошу его амулет.",
    [4881] = "Предупредите Канати Серое Облако на заставе Белого Плеса, что на него готовится покушение.",
    [4882] = "Отнесите ожерелье синих перьев Труллу Баловню Судьбы на Заставу Отравленной Крови.",
    [4883] = "Отнесите ожерелье синих перьев Наре Буйногривой.",
    [4901] = "Защитите Раншаллу, пока она пытается активировать алтарь Элуны. Сообщите о ваших находках Эреласу Янтарному Небу в деревне Рут'теран.",
    [4902] = "Поговорите с верховным друидом Фэндралом Оленьим Шлемом в Дарнассе.",
    [4903] = "Убейте вождя Омокка, воеводу Вуна и повелителя Змейталака. Найденные при них важные бумаги Черной горы доставьте полководцу Клинозубу в Каргат.",
    [4904] = "Выведите Лакоту Песню Ветра с Пика Темного Облака, а потом поговорите с Талией Янтарной Шкурой на Заставе Вольного Ветра.",
    [4906] = "Эридана Грусть Ветра из Оскверненного леса просит вас убить 8 призывателей огня, 8 предателей и 8 плутов из племени Нефритового огня, а также Ксаварика. По выполнении задания возвращайтесь к Эридане.",
    [4907] = "Поговорите с Тинки Кипеллер.",
    [4921] = "Отыщите жену Манкрика и возвращайтесь к нему в Перекресток.",
    [4941] = "Поговорите с Эйтриггом в Оргриммаре. После этого обратитесь к вождю Траллу. В последний раз Эйтригг был в в зале приемов Тралла.",
    [4961] = "Убейте демона сферы, а потом поговорите с Табетой.",
    [4962] = "Возьмите рубин Сквернолова и поймайте в него одну из гончих скверны в Пустошах. Добившись успеха, отнесите плененный дух Гончей Скверны и рубин Сквернолова Менаре Расщепительнице Бездны из Степей.",
    [4963] = "Возьмите Пылающий изумруд и поймайте в него одного из инферналов в Пустошах. Добившись успеха, отнесите плененный дух инфернала и пылающий изумруд Менаре Расщепительнице Бездны из Степей.",
    [4964] = "Дождитесь, пока Менара Расщепительница Бездны закончит работу над шаром Дар'орахила, и еще раз поговорите с ней.",
    [4965] = "Поговорите с Менарой Расщепительницей Бездны в Степях.",
    [4966] = "Защитите Канати Серое Облако от нападения кентавров.",
    [4967] = "Поговорите с Менарой Расщепительницей Бездны в Степях.",
    [4968] = "Поговорите с Менарой Расщепительницей Бездны в Степях.",
    [4969] = "Поговорите с Менарой Расщепительницей Бездны в Степях.",
    [4970] = "Соберите 5 кусков мяса медведей-щеброзуба и 5 кусков мяса стылодыхов для Риверна Холодного Ветра в Зимних Ключах.",
    [4971] = "Воспользуйтесь временным переместителем рядом с одним из амбаров Андорала и найдите временных паразитов. Убейте 10 временных паразитов и верните временной переместитель Хроми в таверну Андорала в Западных Чумных землях.",
    [4972] = "Найдите 5 часов Андорала, спрятанных в сундуки среди руин. Принесите их Хроми в таверну Андорала в Западных Чумных землях.",
    [4973] = "Найдите 5 часов Андорала, спрятанных в сундуки среди руин. Принесите их Хроми в таверну Андорала в Западных Чумных землях.",
    [4974] = "Пойдите в Пик Черной горы и убейте вождя Ренда Чернорука. Принесите его голову в Оргриммар.",
    [4975] = "Дождитесь, пока Менара Расщепительница Бездны закончит работу над шаром Дар'орахила, и еще раз поговорите с ней.",
    [4976] = "Отнесите очищенную сферу инфернала Менаре Расщепительнице Бездны в Степи.",
    [4981] = "Отправьтесь к пику Черной горы и выясните, что сталось с Блестяшкой.",
    [4982] = "Найдите вещи Блестяшки и верните их владелице. Блестяшка сказала, что она спрятала свое оборудование где-то на нижнем ярусе подземелья.",
    [4983] = "Передайте донесение Блестяшки гроссмейстеру Лекслорту в Каргат.",
    [4984] = "Убейте 8 больных волков и вернитесь к Мулгрису Глубокой Реке в Удел Страданий в Западных Чумных землях.",
    [4985] = "Убейте 8 болезненных гризли и вернитесь к Мулгрису Глубокой Реке в Удел Страданий в Западных Чумных землях.",
    [4986] = "Судя по магии, вложенной в покрытую письменами дубовую ветвь, друид-таурен желал отнести ее в Круг Кенария в Дарнассе. Попросите о помощи одного из тамошних друидов.",
    [4987] = "Судя по магии, записанной в покрытую письменами дубовую ветвь, друид-таурен желал отнести ее в Круг Кенария в Громовом Утесе. Попросите о помощи одного из тамошних друидов.",
    [5001] = "Найдите вещи Блестяшки и верните их владелице. Удачи!",
    [5002] = "Передайте маршалу Максвеллу информацию Блестяшки.",
    [5021] = "Судя по сбивчивым объяснениям призрачной женщины, она хочет доставить посылку. Бедняга уверяет, что посылка лежала там, где стоял ее конь. Где именно это было, женщина не сказала.",
    [5022] = "Выясните у королевских представителей Переписи Штормграда местонахождение Эммы Фелстоун. Офицера-переписчика можно найти в Ратуше.",
    [5023] = "Поговорите с королевскими инспекторами Подгорода и наведите справки о Иеремии Фелстоуне. Офицера-переписчика можно найти рядом с пунктом регистрации гильдий и гербовых накидок.",
    [5041] = "Найдите и верните Торку из Степей ящики с припасами из Перекрестка.",
    [5047] = "Переговорите с Малифоем Черномолотом в Круговзоре.",
    [5048] = "Найдите в Штормграде старушку Эмму и узнайте, действительно ли она – Эмма Фелстоун. Если да, то, может, ей понравится та посылочка, что собрала для нее Джанис Фелстоун.",
    [5049] = "Найдите в Подгороде Иеремию Пэйсона и выясните, в самом ли деле он Иеремия Фелстоун. Если да, передайте ему посылку от Джанис Фелстоун.",
    [5050] = "Отнесите половинку талисмана Джанис Фелстоун в Западные Чумные земли.",
    [5051] = "Отыщите вторую половину оберега Удачи на ферме Фелстоун в Западных Чумных землях и соберите его. Отдайте оберег Удачи Джанис Фелстоун.",
    [5052] = "Принесите кровавый осколок Кривозубу в Лагерь Таурахо в Степи. Соберите побольше кровавых осколков, и он одарит вас силой, дарованной ему Агамагганом.",
    [5054] = "По просьбе Шторма Призрачное Копыто в Круговзоре в Зимних Ключах убейте Урсиуса.",
    [5055] = "Убейте Брумеран по просьбе Шторма Призрачное Копыто в Круговзоре в Зимних Ключах.",
    [5056] = "Убейте Ши-Ротам для Шторма Призрачное Копыто.",
    [5057] = "Отнесите Знак Шторма Призрачное Копыто Мелору Каменное Копыто в Громовой Утес.",
    [5061] = "Вернитесь в Дарнасс и покажите Матренгилу Медвежьей Лапе свою подвеску Морского Льва.",
    [5062] = "Соберите 10 листов огненной агавы и поговорите с Магатой Зловещим Тотемом на Вершине Старейшин в Громовом Утесе.",
    [5063] = "Для изготовления шапки Алого Ученого вам нужно принести Малифою Черномолоту 1 Безупречную звериную шкуру; 5 кусков потертого шовного материала поганища; 8 чародейских кристаллов; 5 зачарованных алых нитей. Вы также должны будете уплатить 50 золотых монет за изготовление головного убора.",
    [5064] = "Найдите и заберите три тайные записки на Пике Темного Облака.",
    [5065] = "Принесите третью и четвертую таблички Мошару геологу Железному Башмаку в Танарис.",
    [5066] = "Найдите командира Ашлама Отважного Кулака в лагере Промозглого Ветра на севере Альтеракских гор.",
    [5067] = "Для изготовления Поножей Аркана вам нужно принести Малифою Черномолоту следующее: 1 безупречную звериную шкуру; 5 кусков потертого шовного материала поганища, 5 арканитовых слитков, 5 порций бальзамировочного состава Снегошепота; Вам придется также заплатить 50 золотых монет за изготовление этого предмета.",
    [5068] = "Для изготовления кирасы кровавой жажды вам нужно будет принести Малифою Чернобойцу следующее: 1 безупречную звериную шкуру; 10 кусков потертого шовного материала поганища; 5 арканитовых слитков; 5 тенекож. Вы также должны будете уплатить 50 золотых монет за изготовление доспеха.",
    [5081] = "Отправляйтесь на пик Черной горы и устраните воеводу Вуна, вождя Омокка и повелителя Змейталака. По выполнении задания вернитесь к маршалу Максвеллу.",
    [5082] = "По просьбе Доновы Снегоноры из Зимних Ключей убейте 8 землепроходцев, 8 дозорных и 8 тотемистов из племени Зимней Спячки.",
    [5083] = "Принесите Донове Снегоноре пустую флягу из-под огненной воды.",
    [5084] = "Исследуйте поселение фурболгов из племени Мертвого Леса в северной части Оскверненного леса в поисках ключа к разгадке.",
    [5085] = "Вернитесь к Донове и сообщите ей о своих находках.",
    [5086] = "Соберите 3 капли ядовитого ужаса и принесите их Донове Снегоноре в Зимние Ключи.",
    [5087] = "Найдите гонцов из племени Зимней Спячки и не позвольте им донести их груз до их деревни.",
    [5088] = "Убейте Арикару. В доказательство принесите ее останки и воспламеняющий порошок Мотеге Огненная Грива на заставу Белого Плеса.",
    [5089] = "Отнесите приказ генерала Драккисата маршалу Максвеллу в Пылающие степи.",
    [5090] = "Разыщите командира Ашлама Отважного Кулака в лагере Промозглого Ветра к северу от Альтеракских гор.",
    [5091] = "Разыщите командира Ашлама Отважного Кулака в лагере Промозглого Ветра к северу от Альтеракских гор.",
    [5092] = "Убейте 10 скелетов-свежевателей и 10 слюнявых вурдалаков на холме Печали. Вернитесь к командиру Ашламу Отважному Кулаку в лагерь Промозглого Ветра в Западных Чумных землях.",
    [5093] = "Отыщите верховного палача Деррингтона. Его базовый лагерь находится у Бастиона, к востоку от Тирисфальских лугов и Подгорода.",
    [5094] = "Отыщите верховного палача Деррингтона. Его базовый лагерь находится у Бастиона, к востоку от Тирисфальских лугов и Подгорода.",
    [5095] = "Найдите верховного палача Деррингтона. Его базовый лагерь расположен в Бастионе к востоку от Тирисфальских лесов и Подгорода.",
    [5096] = "Отправляйтесь в лагерь Алого ордена между полем Джанис и Слезами Далсона и уничтожьте командный шатер. Разместите в лагере знамя Плети и возвращайтесь к верховному палачу Деррингтону в Бастион, в Западные Чумные земли.",
    [5097] = "Отметьте все башни Андорала при помощи сигнального факела; задействовать факел следует, находясь в дверном проеме каждой из башен. Отметив все четыре башни, следует вернуть сигнальный факел командиру Ашламу Отважному Кулаку в лагерь Промозглого Ветра в Западных Чумных землях.",
    [5098] = "Отметьте все башни Андорала при помощи сигнального факела; задействовать факел следует, находясь в дверном проеме каждой из башен. Отметив все четыре башни, следует вернуть сигнальный факел командиру Ашламу Смелонраву в лагерь Холодного Ветра в Западных Чумных землях.",
    [5102] = "Отправьтесь на пик Черной горы и устраните генерала Драккисата. По выполнении задания вернитесь к маршалу Максвеллу.",
    [5103] = "Наверняка в этом мире есть кто-то, кто знает, что делать с этими рукавицами.",
    [5121] = "По просьбе Доновы Снегоноры из Зимних Ключей убейте верховного вождя племени Зимней Спячки.",
    [5123] = "Отнесите неразборчиво исписанный журнал Донове Снегоноре в Зимние Ключи.",
    [5124] = "Принесите Малифою Черномолоту 6 зачарованных ториевых слитков, 2 субстанции Огня и 4 звездных рубина. Вам также нужно будет расстаться с неопалимыми латными рукавицами.",
    [5126] = "Поговорите с Лораксом. Выслушайте то, что он вам расскажет.",
    [5127] = "Отправляйтесь на пик Черной горы и найдите Горалука Треснувшую Наковальню. Убейте его, а потом воткните в труп окровавленную пику. Таким образом пика вытянет его душу и окрасится ей. Кроме того, вам нужно найти заготовку рунической кирасы. Отнесите пику и кирасу Лораксу в Зимних Ключах.",
    [5128] = "Отнесите неразборчиво исписанный журнал Келеку Стражу Неба в южную часть Оскверненного леса.",
    [5141] = "Принесите 2 прочные кирасы скорпида, 2 пары прочных перчаток скорпида и 10 потертых чешуек дракона Питеру Галену в Азшару. По выполнении этого задания вы получите возможность обучения кожевничеству школы чешуи драконов. Если вы выполните это задание, вы не сможете изучать кожевничество школы традиций предков и школы силы стихий.",
    [5142] = "Найдите Памелу Редпат.",
    [5143] = "Принесите дикарский кожаный жилет и дикарский кожаный шлем Кариссии Лунной Охотнице из Фераласа. Выполнив это задание, вы станете кожевником школы традиций предков. Также вы лишитесь возможности изучать кожевничество школы чешуи драконов и школы силы стихий; убедитесь, что избрали именно этот путь, прежде чем выполнять задание.",
    [5144] = "Принесите Саре Дубильщице 2 сердца огня, 2 сферы воды, 2 ядра земли и 2 дыхания ветра. Выполнение этого задания позволит вам изучать кожевничество школы силы стихий. Кроме того, вы откажетесь от изучения  кожевничества школ чешуи драконов и традиций предков. Нужно быть уверенным, что выбрана верная школа, прежде чем выполнять задание.",
    [5145] = "Принесите 2 прочные кирасы скорпида, 2 пары прочных перчаток скорпида и 10 потертых чешуек дракона Торкафу Оку Дракона в Бесплодные земли. По выполнении этого задания вы получите возможность обучения кожевничеству школы чешуи драконов. Если вы выполните это задание, вы не сможете изучать кожевничество школы традиций предков и школы силы стихий.",
    [5146] = "Принесите Брумну Заиндевевшему Копыту на нагорье Арати 2 сердца огня, 2 сферы воды, 2 ядра земли и 2 дыхания ветра. Выполнение этого задания позволит вам изучать кожевничество школы силы стихий. Кроме того, вы откажетесь от изучения  кожевничества школ чешуи драконов и традиций предков. Нужно быть уверенным, что выбрана верная школа, прежде чем выполнять задание.",
    [5147] = "Убейте Арнака Зловещий Тотем и принесите доказательство дозорному утесов Долгорогу на Заставу Вольного Ветра.",
    [5148] = "Принесите дикарский кожаный жилет и дикарский кожаный шлем Кариссии Лунной Охотнице из Фераласа. Выполнив это задание, вы станете кожевником школы традиций предков. Также вы лишитесь возможности изучать кожевничество школы чешуи драконов и школы силы стихий; убедитесь, что избрали именно этот путь, прежде чем выполнять задание.",
    [5149] = "Найдите куклу Памелы.",
    [5151] = "Убейте зверя и принестите механизм гипервместимости и ключ от клетки пантеры Визло Фингалету.",
    [5152] = "Поговорите с Марлен в южной части руин Андорала.",
    [5153] = "Принесите Хроми обручальное кольцо Джозефа.",
    [5154] = "Принесите Анналы Дарроушира Хроми в Андорал.",
    [5155] = "Отправляйтесь в Джеденар и убейте 4 джеденарских гончих, 4 джеденарских стражей, 6 джеденарских адептов и 6 джеденарских сектантов, затем возвращайтесь к Грете Заиндевевшее Копыто в Оскверненный лес.",
    [5156] = "Найдите и уничтожьте 2 энтропических зверей и 2 энтропических ужасов при обследовании долины Рваных Ран. После проверьте, по-прежнему ли заполнены кратеры оскверненной водой. Затем возвращайтесь к Таруну Красному Перу в Оскверненный лес.",
    [5157] = "Возьмите пустую флягу и наполните ее водой из лунного колодца, что находится в центре Джеденара. Возвращайтесь к Грете Замшелому Копыту в Оскверненный лес.",
    [5158] = "Отнесите порченую воду из Лунного колодца Ислен Заклинателю Воды в Степи.",
    [5159] = "Отнесите очищенную воду из лунного колодца Грете Замшелому Копыту в Оскверненный лес.",
    [5160] = "Дойдите до Зимних Ключей и найдите Халех. Отдайте ей пластину чешуи Ауби.",
    [5161] = "Если у вас есть желание продолжить, поговорите снова с Халех.",
    [5162] = "Поговорите с Джезибой в Чумных землях. Он обитает в Андорале.",
    [5163] = "Возьмите механического йети Уми и напугайте им ее друзей: Легакки в Круговзоре (Зимние Ключи) поливалку в Прибамбасске (Танарис) Квикксиля в Укрытии Маршалла (Кратер Ун'Горо) Когда проделаете все это, принесите механического йети обратно Уми.",
    [5164] = "Прочитайте перечень Заблудших.",
    [5165] = "При помощи очищенной воды из лунного колодца загасите пламя в четырех жаровнях защиты внутри Оплота Теней в Оскверненном лесу. Затем возвращайтесь к Грете Замшелому Копыту в Изумрудное святилище.",
    [5166] = "Джезиба \"Скульптор\" может сковать кирасу Всецветных драконов, если вы принесете ему следующее: 1 всецветный панцирь. 10 сверкающих всецветных чешуек. 10 порций крови героев. 10 мотков потертого шовного материала.",
    [5167] = "Джезиба 'Скульптор' может сковать ножные латы Всецветного воина, если вы принесете ему следующее: 1 всецветный панцирь. 10 сверкающих всецветных чешуек. 10 порций крови героев. 5 Шкур Тени.",
    [5168] = "Принесите книгу Дейвила и щит Крассена Карлину Редпату.",
    [5181] = "Принести череп Хоргуса и сломанный меч Мардука Карлину Редпату в Часовню Последней Надежды.",
    [5201] = "По заданию Риверна Холодного Ветра убейте 5 шаманов и 5 ведмедей из клана Зимней Спячки.",
    [5202] = "Обыщите Джеденар и найдите замок, который открывается странным красным ключом.",
    [5203] = "Сопроводите Арко'нарин туда, где лежат меч Светлая Сталь и снаряжение Арконарин, и защитите ее при побеге из Оплота Теней. Потом разыщите Джессиру Лунную Радугу в Оскверненном лесу и расскажите ей, что случилось с ее друзьями.",
    [5204] = "Вернитесь в Джеденар и убейте суккуба Ракайю, затем отыщите останки Трея Светогорна.",
    [5206] = "Принесите 5 резонирующих черепов и загадочный кристалл Карлину Редпату в Восточные Чумные земли.",
    [5210] = "Отнесите дополненные Анналы Дарроушира Карлину Редпату в Восточные Чумные земли.",
    [5211] = "Освободите 15 духов Дарроушира и возвращайтесь к Карлину Редпату.",
    [5212] = "Принесите 20 препаратов чумной плоти из Стратхольма Бетине Биггльцинк. Предположительно, любая тварь из Стратхольма сойдет за препарат.",
    [5213] = "Отправляйтесь в Стратхольм и исследуйте зиккураты. Доставьте сведения о Плети Бетине Биггльцинк.",
    [5214] = "Найдите табачную лавку Эзры Гримма в Стратхольме, отыщите в ней коробку отличного табака Эзры Гримма и принесите ее Дымку ЛаРу.",
    [5215] = "Поговорите с верховной жрицей Макдонелл на Берегу Промозглого Ветра в Западных Чумных землях.",
    [5216] = "Отправляйтесь на поле Джанис в Западных Чумных землях, найдите и одолейте Хранителя котла, взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка c поля Джанис.",
    [5217] = "Принесите полную бутылку с поля Джанис верховной жрице Макдонелл в Лагерь Промозглого Ветра, что в Западных Чумных землях.",
    [5219] = "Отправляйтесь в Слезы Далсона в Западных Чумных землях, найдите и одолейте Хранителя котла, взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка c поля Слез Далсона.",
    [5220] = "Принесите полную бутылку с поля Слез Далсона верховной жрице Макдонелл в Лагерь Промозглого Ветра, что в Западных Чумных землях.",
    [5222] = "Отправляйтесь в Удел Страданий в Западных Чумных землях. Найдите и одолейте Хранителя котла. Взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка с Удела Страданий.",
    [5223] = "Принесите полную бутылку с Призрачной фермы верховной жрице Макдонелл в Лагерь Промозглого Ветра, в Западные Чумные земли.",
    [5225] = "Отправляйтесь на пустошь Гаррона в Западных Чумных землях, найдите и одолейте Хранителя котла, взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка с путоши Гаррона.",
    [5226] = "Отнесите полную бутылку с пустоши Гаррона высшей жрице Макдонелл в Лагерь Промозглого Ветра, что в Западных Чумных землях.",
    [5228] = "Поговорите со жрицей Тьмы Вандис в Бастионе, что в Западных Чумных землях.",
    [5229] = "Отправляйтесь на поле Джанис в Западных Чумных землях, найдите и одолейте Хранителя котла, взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка c поля Джанис.",
    [5230] = "Принесите полную бутылку с поля Джанис жрице Тьмы Вандис в Бастион, что в Западных Чумных землях.",
    [5231] = "Отправляйтесь в Слезы Далсона в Западных Чумных землях, найдите и одолейте Хранителя котла, взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка c поля Слез Далсона.",
    [5232] = "Отнесите полную бутылку с поля Слез Далсона жрице Тьмы Вандис в Бастион в Западных Чумных землях.",
    [5233] = "Отправляйтесь в Удел Страданий в Западных Чумных землях. Найдите и одолейте Хранителя котла. Взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка с Удела Страданий.",
    [5234] = "Принесите полную бутылку с Призрачной фермы жрице Тьмы Вандис в Бастион, что в Западных Чумных землях.",
    [5235] = "Отправляйтесь на пустошь Гаррона в Западных Чумных землях, найдите и одолейте Хранителя котла. Взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка с путоши Гаррона.",
    [5236] = "Отнесите полную бутылку с пустоши Гаррона жрице Тьмы Вандис в Бастион в Западных Чумных землях.",
    [5241] = "Найдите Карлина Редпата.",
    [5242] = "Убейте Моору и Салию и принесите голову владыки теней Скверн'дана Грете Замшелому Копыту в Оскверненный лес.",
    [5243] = "Отправляйтесь на север, в Стратхольм. Обыщите брошенные ящики с припасами и соберите 5 мер святой воды Стратхольма. Возвращайтесь к Леониду Бартоломею Чтимому, как только воды будет достаточно.",
    [5244] = "Поговорите с Джероном Гранильщиком в деревне Звездопада.",
    [5245] = "Используйте кирку Джерона, чтобы добыть фрагменты реликвии высокорожденных, Принесите их Авроре Зову Небес в Восточные Чумные земли.",
    [5246] = "Найдите Священные письмена высокорожденных в Храме Зин-Малор, в Азшаре и принесите их Авроре Зову Небес к Башне Северного перевалa, в Восточных Чумных землях.",
    [5247] = "Принесите зачарованный слиток тория, 5 кристаллов Восстановления и фиал пугающей воды Авроре Зову Небес к башне Северного Перевала, в Восточных Чумных землях.",
    [5248] = "Отнесите кристалл Зин-Малора к озеру Кел'Терил в Зимних Ключах и найдите духа высокорожденного, который согласится с вами поговорить.",
    [5249] = "Найдите в Зимних Ключах деревню Звездопада и поговорите там с Вундом Ночным Охотником.",
    [5250] = "Найдите в Зимних Ключах деревню Звездопада и поговорите там с Вундом Ночным Охотником.",
    [5251] = "Отправляйтесь в Стратхольм и отыщите архивариуса Галфорда из Алого ордена. Убейте его и сожгите архив Алых.",
    [5252] = "Поговорите с Вундом Ночным Охотником в деревне Звездопада и узнайте у него, куда нужно поместить кристалл Зин-Малора.",
    [5253] = "Доставьте Кристалл Зин-Малора верховному друиду Фэндралу Оленьему Шлему в Дарнасс.",
    [5261] = "Поговорите с Иганом Меховщиком.",
    [5262] = "Отнесите голову Бальназара герцогу Николасу Зверенхоффу в Восточные Чумные земли.",
    [5263] = "Отправляйтесь в Стратхольм и убейте барона Ривендера. Принесите его голову герцогу Николасу Зверенхоффу.",
    [5264] = "Поговорите с лордом Максвеллом Тироссом. Вы найдете его внутри храма.",
    [5265] = "Откройте Серебряный Оплот и получите награду.",
    [5281] = "Найдите Эгана. В последний раз его видели недалеко от Стратхольма.",
    [5282] = "Стреляйте в призраков и неупокоенных на улицах Стратхольма из излучателя Эгана. Когда душа вырвется из призрачной оболочки, выстрелите в нее еще раз, и она обретет свободу. Освободите 15 неупокоенных душ и возвращайтесь к Эгану.",
    [5283] = "Изготовьте и отдайте Грумнусу 4 узорчатых мифриловых шлема, 2 узорчатых мифриловых сапога и 1 узорчатую мифриловую кирасу.",
    [5284] = "Сделайте и отдайте Железнусу 4 палаша лунной стали, 4 массивных железных топора, 2 тяжелых мифриловых топора и 2 большие черные палицы.",
    [5301] = "Чтобы присоединиться к школе Брони, изготовьте и отдайте Окотосу 4 изысканных мифриловых шлема, 2 пары изысканных мифриловых сапог и 1 изысканную мифриловую кирасу.",
    [5302] = "Изготовьте и отдайте Боргошу 4 палаша лунной стали, 4 массивных железных топора, 2 тяжелых мифриловых топора и 2 больших черных палицы.",
    [5305] = "Отправляйтесь в Стратхольм и убейте Молотобойца из Багрового легиона. Возьмите его фартук и возвращайтесь к Лилит.",
    [5306] = "Отправляйтесь на Пик Черной горы, убейте Темную охотницу Вос'гаджин. Заберите у нее змеекамень и принесите Килраму.",
    [5307] = "Найдите в Стартхольме оружейника Черной Стражи и уничтожьте его. Возьмите его Знак Черной Стражи и принесите Сирилу Плетебою.",
    [5321] = "Сопроводите Керлониана Вечный Сумрак к Лиладрис Лунной Реке по дороге на юг и помогите ему отыскать его вещмешок на Темных берегах.",
    [5341] = "Отправляйтесь в Некроситет и добудьте сокровище семьи Баровых. Оно состоит из четырех документов: на Каэр Дарроу, на Брилл, на Мельницу Таррен и на Южнобережье. После выполнения задания вернитесь к Алексию Барову.",
    [5342] = "Отправляйтесь в Лагерь Промозглого Ветра – на земли Альянса – и убейте Велдона Барова. Отнесите его голову Алексию Барову. Соблюдайте осторожность – скорее всего, Велдона охраняет мразь Альянса.",
    [5343] = "Отправляйтесь в Некроситет и добудьте сокровище семьи Баровых. Оно состоит из четырех документов: на Каэр Дарроу, на Брилл, на Мельницу Таррен и на Южнобережье. После выполнения задания вернитесь к Велдону Барову.",
    [5344] = "Отправляйтесь в Бастион – на земли Орды – и убейте Алексия Барова. Отнесите его голову Велдону Барову. Соблюдайте осторожность – скорее всего, Алексия охраняет ордынская мразь.",
    [5361] = "Доставьте отчет стража утеса Долгорога Натаке Длинному Рогу на Заставу Скитающихся Духов в Пустоши.",
    [5381] = "Добудьте в Крепости Громового Топора Демоническую шкатулку, а затем принесите ее и кирку демонов Тайге Мудрой Гриве в Деревню Ночных Охотников.",
    [5382] = "Найдите в Некроситете доктора Теолена Крастинова. Убейте его, затем сожгите останки Евы и Люсьена Саркофф. Выполнив задание, возвращайтесь к Еве Саркофф.",
    [5384] = "Вернитесь в Некроситет с кровью невинных. Найдите балкон и вылейте кровь в жаровню. На зов явится Киртонос. Сражайтесь как герой, не сдавайтесь! Уничтожьте Киртоноса и возвращайтесь к Еве Саркофф.",
    [5385] = "Принесите останки Трея Светогорна Джессире Лунной Радуге в Оскверненный лес.",
    [5386] = "Отправляйтесь в Деревню Ночных Охотников и поговорите с Джинар'Зилленом, а затем принесите Натаке Длинному Рогу 2 рыбы-кровобрюха.",
    [5441] = "Проучите ленивых батраков дубинкой старшины. Разбудите 5 батраков, потом верните дубинку штейгеру Тазз'рилу в долине Испытаний.",
    [5461] = "Отправляйтесь в высокогорья Арати, в руины Стромгарда. Поищите в Стромгарде книгу Воспоминаний. Если удастся ее отыскать, отнесите ее мировому судье Мардуку.",
    [5462] = "Отправляйтесь в часовню Светлых надежд в Восточных Чумных землях и найдите Леонида Бартоломея Чтимого. Покажите ему книгу Воспоминаний и расскажите обо всем, о чем удалось узнать.",
    [5463] = "Отправляйтесь в Стратхольм и отыщите Дар Менетила. Положите книгу Воспоминаний на оскверненную землю.",
    [5464] = "Отнесите Книгу Души Леониду Бартоломею в Восточные Чумные земли.",
    [5465] = "Возвращайтесь к мировому судье Мардуку в Каэр Дарроу. Покажите ему Книгу Души.",
    [5466] = "Отыщите в Некроситете Раса Снегошепота. Найдя его, воспользуйтесь Книгой Души против его посмертного облика. Если удастся превратить Раса в смертного, убейте его и заберите человеческую голову Раса Снегошепота. Отнесите голову мировому судье Мардуку.",
    [5481] = "Соберите 3 ветки мракоцвета для младшего аптекаря Холланда на кладбище Брилла.",
    [5482] = "Соберите 10 веток погибельника для младшего аптекаря Холланда.",
    [5501] = "Принесите 10 костей с Кладбища кодо в хижину Кормека и отдайте Биббли Скобкофузу.",
    [5504] = "Принесите 10 знаков доблести Серебряного Рассвета интенданту Хасане в Бастион.",
    [5507] = "Принесите 10 знаков доблести Серебряного Рассвета интенданту Искре Света в Лагерь Промозглого Ветра.",
    [5513] = "Принесите 10 знаков доблести Серебряного Рассвета интенданту Затвор в Часовню Последней Надежды в Восточные Чумные земли.",
    [5514] = "Отнесите Кринкелю Сталлинну из Прибамбасска прочные фрагменты скелета и 15 золотых монет.",
    [5515] = "Найдите в Некроситете Джандис Баров и уничтожьте ее. Заберите мешок ужасов Крастинова. Отнесите мешок Еве Саркофф.",
    [5517] = "Принесите 25 знаков доблести Серебряного Рассвета интенданту Затвор в Часовню Последней Надежды в Восточные Чумные земли.",
    [5518] = "Принесите 4 рулона рунной ткани, 8 кусков прочной кожи, 2 мотка рунной нити и огрскую дубильную кислоту Уззлу Наперстяку. Он прикован в секторе Гордока в Забытом Городе.",
    [5521] = "Принесите 25 знаков доблести Серебряного Рассвета интенданту Искре Света в Лагерь Промозглого Ветра.",
    [5522] = "Принесите охлажденные яйца Леониду Бартоломею в Восточные Чумные земли.",
    [5524] = "Принесите 25 знаков доблести Серебряного Рассвета интенданту Хасане в Бастион, что в Западных Чумных землях.",
    [5526] = "Отыщите Сквернит в Забытом Городе и подберите его осколок. Есть шанс, что вам удастся его добыть, только убив Алззина Вертоградаря. Крепко заприте осколок в реликварии Чистоты, затем верните его Рабину Сатурне в Ночную Гавань в Лунной поляне.",
    [5527] = "Отправляйтесь в Силитус и найдите реликварий Чистоты в руинах деревни Южного Ветра. Если вам удастся его найти, возвращайтесь к Рабину Сатурне в Ночную Гавань в Лунной поляне.",
    [5529] = "Убейте 20 зачумленных детенышей дракона, затем возвращайтесь к Бетине Биггльцинк в Часовню Последней Надежды.",
    [5531] = "Принесите охлажденные яйца Бетине Биггльцинк.",
    [5533] = "Поговорите с алхимиком Арбингтоном с вершины Холодной Скалы, что в Западных Чумных землях.",
    [5534] = "Найдите некую руну, которую хранят наги в руинах Эльдарата и принесите ее Ким'джаелю в Азшару.",
    [5535] = "Уничтожьте по 6 теней высокорожденных обоих полов и возвращайтесь к Ло'хату в Азшару.",
    [5536] = "Уничтожьте 6 сатиров, 2 плутов Халдарра и 2 скверноподданных из племени Халдарр и возвращайтесь к Ло'хату к границе Ясеневого леса.",
    [5537] = "Принесите 15 фрагментов скелетов алхимику Арбингтону в Берег Промозглого Ветра в Западных Чумных землях.",
    [5538] = "Отнесите Кринкелю Сталлинну из Прибамбасска прочные фрагменты скелета и 15 золотых монет.",
    [5541] = "Доставьте боеприпасы Хегнару Громострелу в Дун Мороге.",
    [5542] = "Убейте 20 карликовых чумных псов, 5 чумных псов и 5 бесноватых чумных псов. По выполнении задания вернитесь к Тириону Фордрингу.",
    [5543] = "Убейте 30 чумных нетопырей и вернитесь к Тириону Фордрингу.",
    [5544] = "Найдите личинок-падальщиков и падальщиков-пожирателей. Убейте побольше и наберите из мяса. Возвращайтесь к Тириону Фордрингу, когда накопите 15 кусков мяса червей-трупоедов.",
    [5545] = "Принесите 8 вязанок дров Раэлен на Лесопилку Восточной долины.",
    [5561] = "Приведите пять прирученных кодо Смиду Заржавеню в Лагерь Заржавня. Не забудьте вернуть ему энергетический инкапсулятор.",
    [5581] = "Уничтожьте 6 порталов на Поле Маннорок, а затем вернитесь к Тайге Мудрой Гриве в Деревню Ночных Охотников.",
    [5582] = "Отнесите здоровую чешую дракона Бетине Биггльцинк в Часовню Последней Надежды в Восточные Чумные земли.",
    [5601] = "Найдите Памелу Редпат в Дарроушире.",
