    [5713] = "Защитите жизнь часового Айнаши, а потом поговорите с Ойнеей на Заставе Мейстры в Ясеневом лесу.",
    [5721] = "Положите сверток с реликвиями на городскую площадь Дарроушира. Предотвратите смерть Дейвила Яркосвета от рук Хоргуса. Не допустите смерти капитана Редпата до появления Редпата Оскверненного. Убейте Редпата Оскверненного. Поговорите с духом Джозефа Редпата, когда он вновь появится на городской площади, затем отправляйтесь к Памеле и поговорите с ней.",
    [5722] = "Обыщите Огненную пропасть в поисках тела Маура Зловещего Тотема и найдите все необычные предметы.",
    [5723] = "Найдите в Оргриммаре Огненную пропасть, убейте 8 троггов и 8 шаманов Огненной пропасти и возвращайтесь к Рахауро в Громовой Утес.",
    [5724] = "Отнесите сумку Маура Зловещего Тотема Рахауро в Громовой Утес.",
    [5725] = "Принесите книги \"Заклинания Тьмы\" и \"Заклятия Пустоты\" Вариматрасу в Подгород.",
    [5726] = "Принесите лейтенантский знак отличия Траллу в Оргриммар.",
    [5727] = "Отнесите лейтенантский знак отличия Нииру Огненному Клинку. Убедите его в своей преданности Пылающему Клинку. Вернитесь к Траллу в Оргриммар.",
    [5728] = "Убейте Баззалана и Жергоша Призывателя Духов и вернитесь в Оргриммар к Траллу.",
    [5729] = "Поговорите с Нииру Огненным Клинком в Оргриммаре.",
    [5730] = "Поговорите с Траллом в Оргриммаре.",
    [5741] = "Отыщите Скипетр Света и принесите его Азору Альдаморту в башню Этель-Ретор.",
    [5742] = "Выслушайте Тириона Фордринга.",
    [5761] = "Спуститесь в Огненную пропасть, убейте Тарагамана Ненасытного и принесите его сердце Нииру Огненному Клинку в Оргриммаре.",
    [5762] = "Отнесите ящик Крейвела Хемингу Эрнестуэю в Тернистую долину.",
    [5763] = "Отнесите рог кодо, принадлежащий Руну, Хемингу Эрнестуэю в Тернистую долину.",
    [5781] = "Отправляйтесь в Крипту – в самой южной части Восточных Чумных земель – и добудьте молот Таэлана. Отнесите его Тириону Фордрингу.",
    [5801] = "Отнесите форму для отливки отмычек и 2 ториевых слитка на вершину Вулкана Огненного Венца в Кратере Ун'Горо. Окуните форму для отливки отмычки в озеро лавы. Получится недоделанная отмычка. Отнесите недоделанную отмычку алхимику Арбингтону на Берег Промозглого Ветра в Западные Чумные земли.",
    [5802] = "Отнесите форму для отливки отмычек и 2 ториевых слитка на вершину Вулкана Огненного Венца в Кратере Ун'Горо. Окуните форму для отливки отмычки в озеро лавы. Получится недоделанная отмычка. Отнесите недоделанную отмычку аптекарю Дитерсу в Бастион, что в Западных Чумных землях.",
    [5803] = "Убейте Аража Призывателя отнесите его скарабея алхимику Арбингтону на Берег Промозглого Ветра, что в Западных Чумных землях.",
    [5804] = "Убейте Аража Призывателя и отнесите его скарабея аптекарю Дитерсу в Бастион, что в Западных Чумных землях.",
    [5821] = "Охраняйте караван Гизлтона на пути мимо деревни кентавров из племени Колкар. О награде поговорите со Смидом в Лагере Заржавня.",
    [5845] = "Отправляйтесь в Северный дол, что в северо-восточной части Восточных Чумных земель и найдите там символ утраченной чести. После этого вернитесь к Тириону Фордрингу.",
    [5846] = "Отправляйтесь на остров Каэр Дарроу в центральной части Чумных земель и поищите там картину.",
    [5848] = "Отправляйтесь в Статхольм в северную часть Чумных земель. Найдите в Бастионе Алого ордена картину \"Символ семейной любви\", спрятанную за другой, изображающей две луны нашего мира. Отнесите картину Тириону Фордрингу.",
    [5861] = "Отправляйтесь к гробнице Утера, которая находится в южных Чумных землях. Покажите Миранде Колдунье подарок Тириона.",
    [5862] = "Поговорите с Мирандой, пусть она наложит на вас Алую иллюзию. Отправляйтесь в Дольный Очаг, покуда она действует, и отнесите подарок Тириона верховному лорду Телану Фордрингу. Дольный Очаг на севере, а Таэлан должен быть внутри Крепости Марденхольд.",
    [5863] = "Анди Линн из Прибамбасска просит уничтожить поселение Песчаного Молота, убив 10 громил и 10 мародеров из клана Песчаного Молота и Гор'марока Опустошителя.",
    [5881] = "Маггран просит вас передать письмо Гришу Выносливому Гонцу у Великого подъемника в Степи.",
    [5892] = "Принесите 10 припасов Железного рудника интенданту Альянса в Дун Болдар.",
    [5893] = "Доставьте 10 припасов Ледяного Зуба интенданту Орды в крепость Северного Волка.",
    [5901] = "Возьмите пустую банку для термитов и отправляйтесь к большим термитникам в Восточных Чумных землях. Наберите 100 термитов Восточных Чумных земель и возвращайтесь к Микки Левину в Бастион в Тирисфальских лесах.",
    [5902] = "Найдите подходящее место на лесопилке Северного Кряжа в Западных Чумных землях и оставьте там бочонок термитов из Чумных земель.",
    [5903] = "Возьмите пустую банку для термитов и отправляйтесь к большим термитникам в Восточных Чумных землях. Наберите 100 термитов Восточных Чумных земель и возвращайтесь к Натаниэлю Дамаху в Лагерь Промозглого Ветра в Восточные Чумные земли.",
    [5904] = "Найдите подходящее место в центре лесопилки Северного Кряжа в Западных Чумных землях и оставьте там бочонок термитов из Чумных земель.",
    [5921] = "При помощи заклинания \"Телепортация: Лунная поляна\" перенеситесь в Лунную поляну. По прибытии поговорите с Дендритом Блеском Звезд в селении Ночная Гавань.",
    [5922] = "При помощи заклинания \"Телепортация: Лунная поляна\" перенеситесь в Лунную поляну. По прибытии поговорите с Дендритом Блеском Звезд в селении Ночная Гавань.",
    [5923] = "Поговорите с Матренгилом Медвежьей Лапой в анклаве Кенария в Дарнассе.",
    [5924] = "Поговорите с Матренгилом Медвежьей Лапой в анклаве Кенария в Дарнассе.",
    [5925] = "Поговорите с Матренгилом Медвежьей Лапой в анклаве Кенария в Дарнассе.",
    [5926] = "Поговорите с Тюраком Руническим Тотемом на Вершине Старейшин Громового Утеса.",
    [5927] = "Поговорите с Тюраком Руническим Тотемом на Вершине Старейшин в Громовом Утесе.",
    [5928] = "Поговорите с Тюраком Руническим Тотемом на Вершине Старейшин в Громовом Утесе.",
    [5929] = "Найдите духа Великого Медведя на северо-западе Лунной поляны и усвойте все, что он расскажет вам о природе медведя. Когда уроки будут закончены, вернитесь к Дендриту Блеску Звезд в Ночную Гавань в Лунной поляне.",
    [5930] = "Найдите духа Великого Медведя на северо-западе Лунной поляны и усвойте все, что он расскажет вам о природе медведя. Когда уроки будут закончены, вернитесь к Дендриту Блеску Звезд в Ночную Гавань в Лунной поляне.",
    [5931] = "Вернитесь в Дарнасс и поговорите с Матренгилом Медвежьей Лапой в анклаве Кенария.",
    [5932] = "Вернитесь в Громовой Утес и поговорите с Тюраком Руническим Тотемом на Вершине Старейшин.",
    [5941] = "Отнесите сумку с реликвиями Хроми в Андорал.",
    [5942] = "Откройте сундук Джозефа ключом Джозефа.",
    [5943] = "Проводите караван Гизлтона через Поле Маннорок. О награде поговорите со Смидом: его можно найти в Лагере Заржавня.",
    [5944] = "Вывести Таэлана Фордринга из Дольного Очага.",
    [5961] = "Поговорите с Натаносом Гнилостенем в Восточных Чумных землях. Он живет в Поместье Маррисов.",
    [5981] = "По просьбе Риверна Холодного Ветра убейте 4 великанов и 4 оберегателей ледяного молота.",
    [6001] = "Посыпьте лунной пылью Кенария камень лунного совуха в Аубердине, чтобы вызвать Лунокогтя. Победите Лунокогтя, чтобы получить силу его тела и духа. Затем поговорите с Матренгилом Медвежьей Лапой в Дарнассе.",
    [6002] = "Посыпьте лунной пылью Кенария Камень Лунного совуха, что между Мулгором и Степями, чтобы вызвать Лунокогтя. Теперь вам надо побороть Лунокогтя, чтобы заслужить его силу духа и тела. Когда выполните это, поговорите с Тюраком Руническим Тотемом в Громовом Утесе.",
    [6004] = "Убейте 2 медиков, 2 охотников, 2 волхвов и 2 рыцарей Алого ордена и вернитесь к Кристе Чернотени в Западных Чумных землях.",
    [6021] = "Принесите голову Зельдарра Управляющему Алену в Часовню Последней Надежды.",
    [6022] = "Отправляйтесь на восток в Перекресток Корина и убейте несколько населяющих его созданий Плети. Соберите 7 кусков живой гнили менее, чем за 10 минут. С помощью ступки и пестика превратите живую гниль в сгущенную гниль.",
    [6023] = "Убейте охотника Радли и кавалериста Даргена и вернитесь к Кристе Чернотени в Западные Чумные земли.",
    [6024] = "Убейте секретного агента Хамейю. С помощью ключа извлеките сокровище из кучи грязи за Криптой.",
    [6025] = "Проберитесь в Дольный Очаг и найдите возвышенность, с которой открывается вид на весь город. Оцените силы Алого ордена и вернитесь к Кристе Чернотени в Западных Чумных землях.",
    [6026] = "Принесите 2 ториевых слитка, 1 золотой жезл, 8 высоковзрывных бомб и 8 нестабильных пусковых устройств Дымку ЛаРу. Для этого вам придется найти кузнеца и инженера.",
    [6027] = "Отыщите Книгу Древних и принесите ее Азору Альдаморту в башню Этель-Ретор.",
    [6028] = "Доставьте донесение из Круговзора офицеру Чистосердой из ордена Серебряного Рассвета в Лагерь Промозглого Ветра в Западных Чумных землях.",
    [6029] = "Доставьте донесение из Круговзора офицеру Гарушу из ордена Серебряного Рассвета в Бастион в Западных Чумных землях.",
    [6030] = "Доставьте книгу \"Исследования речи духов\" Герцогу Николасу Зверенхоффу в Часовню Последней Надежды в Восточных Чумных землях.",
    [6031] = "Принесите 30 отрезов рунной ткани Мелиошу в крепость Древобрюхов.",
    [6032] = "Принесите 2 отреза луноткани Мелиошу в Крепость Древобрюхов.",
    [6041] = "Отправляйтесь в Проклятый лес, к северо-западу от часовни Светлых надежд. Уничтожьте 8 строений Плети, отмеченных знаком взрыва, поместив особый состав Дымка внутрь строения. Дымок отметил зиккураты и бойни. Разместив бомбу внутри строения, немедленно выбирайтесь наружу и любуйтесь делом рук своих с безопасного расстояния. Ах да, вот еще что, особый состав Дымка – вещество весьма нестабильное.",
    [6042] = "Истребите 20 пагубных нетопырей и 10 чудовищных чумных нетопырей. После возвращайтесь к Натаносу Гнилостеню.",
    [6061] = "Приручите взрослого равнинного долгонога при помощи хлыста приручения. Потренируйтесь и верните хлыст Йо Колкой Гриве в Деревне Кровавого Копыта.",
    [6062] = "Приручите лютого пятнистого вепря с помощью хлыста приручения. Потренируйтесь, потом верните хлыст приручения Тотару в Колючем Холме.",
    [6063] = "С помощью хлыста приручения приручите чащобного тенетника. Поупражняйтесь, затем верните хлыст приручения Дазалару в Доланаар.",
    [6064] = "Приручите большого скального вепря с помощью хлыста приручения. Потренируйтесь со своим новым питомцем, а затем верните хлыст приручения Грифу Дикому Сердцу в Каранос.",
    [6065] = "Поговорите с Йо Колкой Гривой в Деревне Кровавого Копыта.",
    [6066] = "Поговорите с Йо Колкой Гривой в Деревне Кровавого Копыта.",
    [6067] = "Поговорите с Йо Колкой Гривой в Деревне Кровавого Копыта.",
    [6068] = "Поговорите с Тотаром в Колючем Холме.",
    [6069] = "Поговорите с Тотаром в Колючем Холме.",
    [6070] = "Поговорите с Тотаром в Колючем Холме.",
    [6071] = "Поговорите в Доланааре с Дазаларом.",
    [6073] = "Поговорите в Доланааре с Дазаларом.",
    [6074] = "Поговорите с Грифом Диким Сердцем в Караносе.",
    [6075] = "Поговорите с Грифом Диким Сердцем в Караносе.",
    [6076] = "Поговорите с Грифом Диким Сердцем в Караносе.",
    [6081] = "Поговорите с Ормаком Лютострелом в Оргриммаре.",
    [6082] = "Приручите бронескорпа с помощью хлыста приручения. Потренируйтесь, потом вернитесь к Тотару в Колючем Холме.",
    [6083] = "Приручите приливного краба с помощью хлыста приручения. Потренируйтесь, потом верните хлыст приручения Тотару в Колючем Холме.",
    [6084] = "Приручите снежного леопарда с помощью хлыста приручения. Потренируйтесь со своим новым питомцем, а затем верните хлыст приручения Грифу Дикому Сердцу в Каранос.",
    [6085] = "Приручите медведя-ледолапа с помощью хлыста приручения. Потренируйтесь со своим новым питомцем, а затем верните хлыст приручения Грифу Дикому Сердцу в Каранос.",
    [6086] = "Поговорите в с Белией Громовым Гранитом в Стальгорне.",
    [6087] = "Приручите охотника прерий при помощи хлыста приручения. Потренируйтесь и верните хлыст Йо Колкой Гриве в Деревне Кровавого Копыта.",
    [6088] = "Приручите перепелятника при помощи хлыста приручения. Потренируйтесь и верните хлыст Йо Колкой Гриве в Деревне Кровавого Копыта.",
    [6089] = "Поговорите с Хольтом Громовым Рогом в Громовом Утесе.",
    [6101] = "С помощью хлыста приручения приручите ночного саблезуба-охотника. Поупражняйтесь, затем верните хлыст приручения Дазалару в Доланаар.",
    [6102] = "С помощью хлыста приручите совиного крикуна. Поупражняйтесь, затем верните хлыст приручения Дазалару в Доланаар.",
    [6103] = "Поговорите с Иокастой в анклаве Кенария в Дарнассе.",
    [6121] = "Отправляйтесь в Лунную поляну и поговорите с Дендритом Блеском Звезд в селении Ночная Гавань.",
    [6122] = "Используйте пустую колбу для взятия пробы воды из устья пещеры у водопада Скалистый. Доставьте наполненную колбу Аландариан Песне Ночи в Аубердин, на Темный Берег.",
    [6123] = "Принесите 5 корешков землекорня и 12 лунных грибов Аландариан Песне Ночи в Аубердине, чтобы она могла сделать целительную мазь.",
    [6124] = "Нанесите мазь исцеления животных на 10 больных оленей, обитающих на Темном Берегу, – это должно их исцелить. По слухам, ареал обитания больных оленей – южнее реки Скалистой и севернее Аубердина, а далее – по всей области, вплоть до южных границ Темного Берега, где начинается Ясеневый лес.",
    [6125] = "Вернитесь к Матренгилу Медвежьей Лапе в анклав Кенария в Дарнассе.",
    [6126] = "Отправляйтесь в Лунную поляну и поговорите с Дендритом Блеском Звезд в селении Ночная Гавань.",
    [6127] = "Используйте пустой пробоотборник Вершины Багрового Тумана для отбора воды из озера на вершине. Доставьте наполненный пробоотборник Вершины Багрового Тумана Тонге Руническому Тотему в Перекресток, что в Степях.",
    [6128] = "Принесите 5 корешков землекорня и 5 рогов кодо Тонге Руническому Тотему в Перекресток, и он сделает целебную мазь.",
    [6129] = "Нанесите мазь исцеления животных на 10 больных газелей, обитающих в северной части Степей, – это должно их вылечить. По слухам, больные газели живут севернее дороги, проходящей через Перекресток с востока на запад.",
    [6130] = "Вернитесь к Тюраку Руническому Тотему на Вершину Старейшин в Громовой Утес.",
    [6132] = "Проводите Мелиццу Жужжалит в лагерь у Кладбища кодо в Пустошах. Поговорите с Хормицем Жужжалитом.",
    [6133] = "Отправляйтесь в северные пределы Восточных Чумных земель и заполучите реестр Кель'Таласа. Документ находится где-то в Сторожке Кель'Литиен. Также убейте 8 следопытов, 8 разведчиц дорог и 8 лесников.",
    [6134] = "Принесите 8 единиц эктоплазмы и ящик призрачных магнитов Хормицу Жужжалиту в Пустоши.",
    [6135] = "Выследите Тенекрыла и убейте его. Принесите полоску меха Тенекрыла Натаносу Гнилостеню. Говорят, Тенекрыл рыщет в землях к северу от имения Марриса.",
    [6136] = "Найдите и уничтожьте Мерзкослиза в северных пустошах Восточных Чумных земель. Возвращайтесь к Натаносу Гнилостеню по выполнению задания.",
    [6141] = "Найдите в Пустошах брата Антона и поговорите с ним.",
    [6142] = "Найдите 10 кусочков мяса мягкокожего моллюска и принесите Май'Лахии в Деревню Ночных Охотников.",
    [6143] = "Убейте 7 мирмидонов, 7 наг и 5 колдуний из клана Скользящего Плавника, а затем вернитесь в деревню Сумеречной Охоты и поговорите с Друлзегаром.",
    [6144] = "Отправляйтесь в Подгород и предстаньте перед Вериматасом.",
    [6145] = "Возвращайтесь в Восточные Чумные земли и выследите курьера из Багрового Легиона. Убейте его и заберите приказ верховного рыцаря. За дальнейшими указаниями обращайтесь к Натаносу Гнилостеню.",
    [6146] = "Отправляйтесь в Длань Тира к юго-востоку от Поместья Маррисов. Прибыв в город, откусите от гнилого яблока. Под личиной рыцаря Алого ордена доставьте приказ верховного рыцаря лорду-рыцарю Вальдермару.",
    [6147] = "Возвращайтесь к Натаносу и отчитайтесь о выполнении задания.",
    [6148] = "Алый орден сейчас в пути. Найдите Оракула Деметрию и ее свиту на дороге от Длани Тира в Стратхольм. Убейте Оракула и возвращайтесь к Натаносу Гнилостеню.",
    [6161] = "Найдите серебряный и золотой ключи Ракмора, а затем разыщите и отоприте сундук Ракмора.",
    [6162] = "Убейте властителя Рора и принесите его коготь Дрейка'Сур на заставу Отравленной Крови в Оскверненном лесу.",
    [6163] = "Отправляйтесь в Стратхольм и убейте Рамштайна Ненасытного. Принесите его голову Натаносу в качестве сувенира.",
    [6164] = "Принесите Августу Помешанному в Долину Ужаса его книгу рецептов.",
    [6181] = "Отнесите записку Льюиса укротителю грифонов Тору.",
    [6182] = "Поговорите с Матиасом Шоу в Старом Городе в Штормграде. Матиас находится в казармах.",
    [6183] = "Еще раз поговорите с Матиасом Шоу, если хотите принять его задание.",
    [6184] = "Отправляйтесь в Лагерь Промозглого Ветра в Западных Чумных землях и найдите Флинта Тенемора.",
    [6185] = "Поищите в Восточных Чумных землях сведения про некоего Гнилостеня и пропавших агентов ШРУ. Если удастся найти знаки отличия ШРУ, отнесите их Флинту Тенемору в Лагерь Промозглого Ветра.",
    [6186] = "Возвращайтесь в Штормград и сообщите верховному лорду Болвару Фордрагону о судьбе Натаноса Марриса.",
    [6187] = "Соберите войско и отправляйтесь в Восточные Чумные земли. Проведите полномасштабную атаку на Натаноса Гнилостеня и любых воинов Орды, которые могут попытаться его защитить. Будьте осторожны, потому что Орда всеми силами будет защищать бывшего предводителя следопытов.",
    [6261] = "Отнесите ящик Озрика к укротителю грифонов Дунгару Долгопиву.",
    [6281] = "Оплатите укротителю грифонов Тору полет до Штормграда и принесите записку Льюиса Озрику Штрангу в магазинчик \"Ограниченная неуязвимость\", расположенный в районе Старого города.",
    [6282] = "Землепряд Маггран из Приюта у Солнечного Камня просит вас убить 7 гарпий, 7 душительниц, 7 душегубок и 7 бродяжниц из стаи Кровавой Ярости.",
    [6283] = "Маггран из Приюта у Солнечного Камня просит убить Потрошительницу из стаи Кровавой Ярости и принести ему ее останки в доказательство того, что она мертва.",
    [6284] = "Убейте Бесселет и принесите клык Бесселет Магграну в Приют у Солнечного Камня.",
    [6285] = "Оплатите укротителю грифонов Дунгару Долгопиву полет до Сторожевого холма, а затем отнесите ящик Озрика Льюису.",
    [6301] = "Таммра Поле Ветров из Приюта у Солнечного Камня просит вас собрать 10 семян Геи.",
    [6321] = "Отнесите заказ Подрига Каросу Раззоку.",
    [6322] = "Отправляйтесь к Майклу Гарретту с ящиком Гордона.",
    [6323] = "Оплатите у дрессировщика летучих мышей Кароса Раззока полет до Подгорода, а затем отнесите заказ Подрига Гордону Уиндему в Подгороде.",
    [6324] = "Оплатите у дрессировщика летучих мышей Майкла Гарретта полет до Гробницы, а затем отдайте ящик Гордона стражу смерти Подригу в Гробнице.",
    [6341] = "Отнесите коллекцию Нессы к Веспристу.",
    [6342] = "Совершите полет в Аубердин на гиппогрифе укротителя Весприста и отнесите коллекцию Нессы Лайрду.",
    [6343] = "Принесите ответ Лайрда Нессе Песне Теней.",
    [6344] = "Поговорите с Нессой Песня Теней.",
    [6361] = "Отнесите связку шкур Зарга укротителю ветрокрылов Девраку из Перекрестка.",
    [6362] = "Оплатите перелет в Громовой Утес укротителю ветрокрылов Девраку и, оказавшись на месте, отнесите связку шкур Ахану.",
    [6363] = "Отнесите кожаные вещи Ахану Талу из Громового Утеса.",
    [6364] = "Оплатите перелет до Перекрестка у укротителя ветрокрылов Тала, а затем отнесите кожаные вещи Ахану Джахану Ястребиному Крылу.",
    [6365] = "Отнесите мясные продукты Зарга Девраку из Перекрестка.",
    [6381] = "Посадите 10 семян Геи в земляные курганы Геи, а затем верните оставшиеся зачарованные семена Геи Таммре в Приют у Солнечного Камня.",
    [6382] = "Поговорите с Сенани Громосерд на заставе Расщепленного Древа в Ясеневом лесу.",
    [6384] = "Оплатите полет в Оргриммар укротителю ветрокрылов Девраку и, оказавшись в Оргриммаре, отнесите мясные продукты Зарга Гришке.",
    [6385] = "Отнесите письмо Гришки Дорасу из Оргриммара.",
    [6386] = "Оплатите перелет в Перекресток укротителю ветрокрылов Доресу и, оказавшись на месте, передайте письмо Гришки Заргху из Перекрестка.",
    [6387] = "Отнесите список Брока Торгруму Боррелсону в Телcамаре.",
    [6388] = "Отнесите почетные кирки Гриту Турдену в Стальгорне.",
    [6389] = "Выпустите термитов с Чумных земель на лесопилке Северного Кряжа и возвращайтесь к Натаниэлю Дамаху в Лагерь Промозглого Ветра в Западные Чумные земли.",
    [6390] = "Выпустите термитов с Проклятых земель на лесопилке Северного Кряжа и возвращайтесь к Микки Левину в Бастион в Тирисфальских лесах.",
    [6391] = "Заплатите укротителю грифонов Торгруму Боррелсону, долетите на грифоне до Стальгорна и отдайте список Брока Голниру Твердопалу.",
    [6392] = "Заплатите укротителю грифонов Гриту Турдену, долетите на грифоне до Телcамара и отдайте почетные кирки Броку Камнекопу.",
    [6393] = "Принесите 10 Огненных кристаллов Цунаману в приют Солнечного Камня.",
    [6394] = "Принесите штейгеру Тазз'рилу его кирку.",
    [6395] = "Отнесите останки Самуэля Фиппса на могилу Марлы, а затем вернитесь к ученице Элрет.",
    [6401] = "Передайте хорошие новости Таммре Поле Ветров, живущей в Приюте у Солнечного Камня.",
    [6402] = "Отправьтесь в Штормград и подойдите к городским воротам. Поговорите с оруженосцем Роу, чтобы он сообщил маршалу Виндзору о вашем прибытии.",
    [6403] = "Сопроводите Реджинальда Виндзора через весь Штормград и защищайте его! Поговорите с оруженосцем Роу, если вам снова нужно будет обратиться к Реджинальду Виндзору.",
    [6421] = "Обследуйте глубины пещеры в ущелье Камнепадов и принесите 10 кристаллов резонита для исследования Мор'рогалу в Приют у Солнечного Камня.",
    [6441] = "Добудьте 16 рогов сатира для Пиксель на заставе Расщепленного Древа.",
    [6442] = "Принесите 20 голов наг из клана Зловещего Хвоста Марукайе на Зорамское взморье.",
    [6461] = "Ксен'Зилла из Малака'джина просит вас убить 10 ползун из густого мха и 7 моховых ядоплюев.",
    [6462] = "Принесите 8 оберегов троллей Митсуве в форт Зорам'гар.",
    [6481] = "Откройте резонитовую емкость при помощи зачарованного кристалла резонита и затем убейте Гоггерока. Вернитесь к Мор'рогалу с новостями и зачарованным кристаллом резонита.",
    [6482] = "Сопроводите Руула, затем поговорите с Ями Снежное Копыто на заставе Расщепленного Древа.",
    [6501] = "Найдите существа, способные вернуть силу фрагменту амулета Ока дракона. Все, что об этих существах известно – это то, что они есть.",
    [6502] = "Добудьте кровь могучего черного дракона у генерала Драккисата. Его можно найти сидящим на троне в залах Вознесения в Пике Черной горы.",
    [6503] = "Убейте 9 вестниц Ясеневого леса, а затем вернитесь к Курай'бину на заставу Расщепленного Древа.",
    [6504] = "Найдите 12 пропавших страниц руководства по использованию резака и соберите их по порядку глав 1, 2 и 3. Верните страницы Гурде Печати Гнева близ заставы Расщепленного Древа.",
    [6521] = "Принести голову посла Малкина Вариматрасу в Подгород.",
    [6522] = "Отнесите маленький свиток Вариматрасу в Подгород.",
    [6523] = "Проводите Кайю Плоское Копыто до Лагеря Апарахе, затем вернитесь к Макабе Плоскому Копыту, находящемуся поблизости от юго-восточного края Каменного Когтя.",
    [6541] = "Доложитесь Кадраку в сторожевой башне в северных Степях.",
    [6542] = "Доложитесь Кадраку в сторожевой башне в северных Степях.",
    [6543] = "Распакуйте связку донесений. Доставьте отчеты Песни Войны разведчику, гонцу и всаднику клана Песни Войны. Возьмите у них новые донесения для Кадрака и доставьте ему в северную сторожевую башню в Степях.",
    [6544] = "Сопровождайте Торека при нападении на Аванпост Среброкрылых и в сражении с Дариэлем Лунным Пламенем, затем доложитесь Эртогу Лютоклыку на заставе Расщепленного Древа.",
    [6548] = "Убейте 8 бузотеров и 6 наемников из племени Зловещего Тотема, затем вернитесь к Макабе Плоскому Копыту, ожидающему вас на юго-восточной границе Когтистых гор.",
    [6561] = "Принесите голову Повелителя сумрака Келриса Башане Руническому Тотему в Громовой Утес.",
    [6562] = "Поговорите с Дже'неу Санкри в Ясеневом лесу.",
    [6563] = "Принесите 20 сапфиров Аку'май Дже'неу Санкри в Ясеневый лес.",
    [6564] = "Принесите отсыревшую записку Дже'неу Санкри в Ясеневый лес.",
    [6565] = "Убейте Лоргуса Джетта в Непроглядной Пучине и вернитесь к Дже'неу Санкри в Ясеневый лес.",
    [6566] = "Выслушайте Тралла.",
    [6567] = "Найдите Рексара. Вождь сказал, что он бродит в Пустошах, по дороге, что ведет из Когтичтых гор в Фералас.",
    [6568] = "Доставьте письмо Рексара Миранде Колдунье в Западные Чумные земли.",
    [6569] = "Отправляйтесь на пик Черной горы и добудьте 20 глаз черных драконидов. По выполнении задания вернитесь к Миранде Колдунье.",
    [6570] = "Отправляйтесь в Драконьи топи в Пылевых топях и найдите Логово Огнебора. Оказавшись внутри, наденьте амулет Обмана драконов и поговорите с Огнебором.",
    [6571] = "Соберите полностью поставку Песни Войны: лезвия для пил, веревку для бревен, масло и партию топоров Песни Войны для Локе Окарра на заставе Расщепленного Древа.",
    [6582] = "Найдите в Зимних Ключах избранного бойца синих дракона по имени Провидец и убейте его. С его черепом вернитесь к Огнебору.",
    [6583] = "Убейте вожака зеленых драконов Сомнуса и вернитесь с его черепом к Огнебору.",
    [6584] = "Убейте Хроналиса, охраняющего Пещеры Времени в Пустыне Танарис и вернитесь с его черепом к Огнебору.",
    [6585] = "Отправьтесь в Грим Батол и убейте Акстроза, избранного бойца красных драконов. Принесите его череп Огнебору.",
    [6601] = "Казалось бы, загадка разгадана. Вы знаете, что амулет Обмана Драконов, который сделала для вас Миранда Колдунья, не будет работать на пике Черной горы. Найдите Рокаро и расскажите о ваших затруднениях. Покажите ему амулет Угасающего Пламени Дракона. Будем надеяться, он знает что делать.",
    [6602] = "Отправляйтесь к пику Черной горы и убейте генерала Драккисата. Соберите его кровь и вернитесь к Рокаро.",
    [6603] = "Найдите Донову Снегонору у горячего источника в Зимних ключах.",
    [6604] = "Поговорите с Джероном Гранильщиком в деревне Звездопада.",
    [6605] = "Поговорите с Винной Хезард в Оскверненном лесу.",
    [6607] = "Поймайте для Ната Пэгла следующих рыб: Махи-махи с берега Туманных Тростников на Болоте Печали. Ударник Сартериса с побережья Сар'Терис из Пустошей. Фералас-ахи из реки Вердантис из Фераласа. Синий плавник Гибельного берега из Тернистой долины. По выполнении вернитесь к Нату Пэглу.",
    [6608] = "Похоже, Лумак хочет сказать, что ему больше нечему вас учить. Возможно, стоит найти его друга Ната Пэгла – человека, который удит рыбу на островах к югу от Терамора. Кажется, Лумак имеет в виду именно это.",
    [6609] = "Отправляйтесь на Калимдор, в приморский город Терамор. Там к югу от города найдите остров. Нат Пэгл уже ждет.",
    [6610] = "Могиль Быстроруб поручил принести ему следующее: 12 гигантских яиц. Их можно отыскать у рухов Танариса или других крупных птиц. 10 кусков острого мяса моллюсков. Разумеется, его добывают у моллюсков! 20 кусков альтеракского сыра. Из сыроварни! Собрав все составляющие, возвращайтесь к Диргу.",
    [6611] = "Отправляйтесь в Прибамбасск в пустыне Танарис и поговорите с Могилем Быстрорубом.",
    [6612] = "Пойдите в Прибамбасск в пустыне Танарис и поговорите с Могилем Быстрорубом насчет продвижения в поварской карьере.",
    [6621] = "Водрузите знамя Каранга на тотемном кургане Гиблой Чащи. Не дайте фурболгам унитожить знамя. Одолейте вождя Мургута и принесите тотем Мургута Карангу Амаккару в Зорам'гар.",
    [6622] = "Окажите помощь пациентам, используя для перевязки их ран очередные перевязочные бинты. Вы должны оказать помощь 15 пациентам прежде, чем 6 из них успеют умереть от ран. Помните о порядке оказания помощи! Находящиеся при смерти солдаты умирают быстрее, чем тяжелораненые. Легкораненые живут дольше всех, потому им надо оказывать помощь ПОСЛЕ того, как перевяжете тех, кто при смерти, и тяжелораненых.",
    [6623] = "Пойдите в Павший Молот на нагорье Арати и поговорите с доктором Грегори Виктором о том, чтобы стать травматологом.",
    [6624] = "Окажите помощь пациентам, используя для перевязки их ран очередные перевязочные бинты. Вы должны оказать помощь 15 пациентам прежде, чем 6 из них успеют умереть от ран. Помните о порядке оказания помощи! Находящиеся при смерти солдаты умрут быстрее, чем тяжелораненые. Легкораненые могут прожить дольше всех, потому им надо оказывать помощь ПОСЛЕ того, как перевяжете тех, кто при смерти, и тяжелораненых.",
    [6625] = "Отправляйтесь в Терамор в Пылевых топях и поговорите с доктором Густавом ван Схлиффом насчет зачисления в травматологи Альянса.",
    [6626] = "Убейте 8 боевых стражей и 8 терноплетов из племени Иглошкурых, а также 8 сектанток из племени Мертвой Головы и возвращайтесь к Мириам Лунной Певице на Курганы Иглошкурых.",
    [6627] = "Дайте верный ответ на вопрос Брауга Тусклого Духа и поговорите с ним еще раз. Брауга можно в любое время найти в Когтистых горах.",
    [6628] = "Дайте верный ответ на вопрос Парквела Финталласа и поговорите с ним еще раз. Парквелла можно в любое время найти в Подгороде.",
    [6629] = "Убейте Грундига Темное Облако и 6 громил из племени Зловещего Тотема и вернитесь к Макабе Плоскому Копыту, который ждет вблизи юго-восточного края Каменного Когтя.",
    [6641] = "Охраняйте Муглаша на его пути к жаровне. Помогите ему погасить жаровню, а затем защищайте его, ведя бой с нагами. Если вам все удастся, возвращайтесь в форт Зорам'гар и сообщите гонцу клана Песни Войны о смерти Ворши Хлестуньи.",
    [6661] = "Поймайте 5 подземных крыс, используя Флейту крысолова, и принесите их Монти. Не забудьте вернуть флейту владельцу.",
    [6662] = "Отвезите Нипси в подземное депо Штормграда коробку таинственного мяса.",
    [6681] = "Отнесите печать Черного Ворона Фахраду в поместье Черный Ворон, сокрытое среди холмов Хилсбрада. Не теряйте бдительности. Поиски поместья – проверка на ловкость.",
    [6721] = "Поговорите в Доланааре с Дазаларом.",
    [6722] = "Поговорите в Доланааре с Дазаларом.",
    [6761] = "Поговорите с Матренгилом Медвежьей Лапой в анклаве Кенария в Дарнассе.",
    [6762] = "Поговорите с Рабином Сатурной в селении Ночная Гавань на Лунной поляне. Лунная поляна находится между Оскверненным лесом и Зимними Ключами, туда можно добраться по дороге, идущей от крепости Древобрюхов.",
    [6804] = "Исцелите отравленных элементалей в Восточных Чумных землях с помощью аспекта Нептулона. Принесите 12 браслетов колыхающихся волноплесков и аспект Нептулона герцогу Гидраксису в Азшару.",
    [6805] = "Убейте 15 пылевихрей и 15 пустынных грохотунов, а затем возвращайтесь к герцогу Гидраксису в Азшару.",
    [6821] = "Принесите глаз Созерцателя Углей герцогу Гидраксису в Азшару.",
    [6822] = "Убейте 1 Повелителя огня, 1 лавового гиганта, 1 древнюю гончую бездны и 1 лавового волноплеска и возвращайтесь к герцогу Гидраксису в Азшару.",
    [6823] = "Добейтесь уважительного отношеия к себе со стороны Гидраксианских Повелителей Вод, затем отправляйтесь к герцогу Гидраксису в Азшару.",
    [6824] = "Принесите руки Люцифрона, Сульфурона, Гееннаса и Шаззраха герцогу Гидраксису в Азшару.",
    [6844] = "Отнесите покрытый коркой предмет Умберу – архивариусу Круга Кенария – в деревню Ночная Гавань, что в Лунной поляне.",
    [6845] = "Поговорите с Рабином Сатурной в деревне Ночная Гавань в Лунной поляне.",
    [6921] = "Принесите глубинный сердечник Дже'неу Санкри в форт Зорам'гар в Ясеневый лес.",
    [6922] = "Принесите странную водяную сферу Дже'неу Санкри в форт Зорам'гар в Ясеневом лесу.",
    [6981] = "Отправляйтесь в Кабестан и найдите там кого-нибудь, кто сможет вам рассказать об этом светящемся осколке. Затем отнесите осколок туда, куда вас направят.",
    [6982] = "Принесите 10 ящиков с припасами Ледяного Зуба интенданту Альянса в Дун Болдар.",
    [6985] = "Доставьте 10 ящиков припасов Железного рудника интенданту Орды в крепость Северного Волка.",
    [7001] = "Найдите северного волка в Альтеракской долине. Подойдите к нему на достаточное расстояние, чтобы его \"приручить\", и используйте намордник Северного Волка. После приручения северный волк проследует за вами к смотрителю стойл из клана Северного Волка. Поговорите со смотрителем, чтобы получить награду за пойманных волков.",
    [7003] = "Используйте ультрасжиматель Зорбина, чтобы уменьшить великанов любого вида, каких вы найдете в Фераласе. Принесите 15 остатков миниатюризации этих великанов Зорбину Дребезгуну в порт Забытого берега в Фераласе.",
    [7027] = "Найдите в Альтеракской долине альтеракского барана. Чтобы приручить барана, используйте учебный ошейник Грозовой Вершины. Для этого надо подойти в барану поближе. Пойманный баран проследует за вами к смотрителю стойл. Поговорите со смотрителем стойл, чтобы получить вознаграждение за пойманных баранов.",
    [7028] = "Соберите 25 терадрических хрустальных орнаментов для Ивы из Пустошей.",
    [7029] = "Наполните церуленовый фиал с покрытием в оранжевом пруду Мародона. Полейте гнусь-лозу из полного церуленового фиала, выгнав ядовитую лозу. Исцелите 8 растений, убивая ядовитые лозы, и вернитесь к Варку Боевому Шраму в Деревню Ночных Охотников.",
    [7041] = "Наполните церуленовый фиал с покрытием в оранжевом пруду Мародона. Полейте гнусь-лозу из полного церуленового фиала, выгнав ядовитую лозу. Исцелите 8 растений, убивая ядовитые лозы, и вернитесь к Талендрии из Высоты Найджела.",
    [7044] = "Добудьте две части скипетра Келебраса – жезл Келебраса и бриллиант Келебраса. Найдите способ поговорить с Келебрасом.",
    [7046] = "Помогите Селебрасу Искупленному воссоздать скипетр Селебраса. По завершении ритуала снова обратитесь к нему.",
    [7064] = "Убейте принцессу Терадрас и вернитесь к Селендре неподалеку от Деревни Ночных Охотников в Пустошах.",
    [7065] = "Убейте принцессу Терадрас и вернитесь к хранителю Марандису на Высоту Найджела в Пустоши.",
    [7066] = "Найдите в Лунной поляне Ремулоса и отдайте ему Семя Жизни.",
    [7067] = "Прочтите инструкции кентавра-парии, добудьте из Мародона амулет Соединения и верните его кентавру-парии из южной части Пустошей.",
    [7068] = "Соберите в Мародоне 10 фрагментов осколков сумрака и отнесите их Утель'наю в Оргриммар.",
    [7070] = "Соберите в Мародоне 10 фрагментов осколков сумрака и отнесите их верховному магу Тервошу в Терамор на побережье Пылевых топей.",
    [7081] = "Захватите кладбище, затем возвращайтесь к сержанту Даргену Грозовой Вершине в Альтеракские горы.",
    [7082] = "Захватите кладбище, затем возвращайтесь к капралу Тике Кровавому Рыку в Альтеракские горы.",
    [7101] = "Захватите башню врага и возвращайтесь к капралу Тике Кровавому Рыку в Альтеракские горы.",
    [7102] = "Уничтожьте вымпел на вражеской башне или бункере и возвращайтесь к сержанту Даргену Грозовой Вершине в Альтеракские горы.",
    [7121] = "Поговорите с интендантом клана Грозовой Вершины.",
    [7122] = "Захватите рудник, который не принадлежит Грозовой Вершине, и возвращайтесь к сержанту Даргену Грозовой Вершине в Альтеракские горы.",
    [7123] = "Поговорите с интендантом клана Северного Волка.",
    [7124] = "Захватите рудник и возвращайтесь к капралу Тике Кровавому Рыку в Альтеракские горы.",
    [7141] = "Отправляйтесь в Альтеракскую долину, сразитесь с генералом Орды Дрек'Таром и возвращайтесь к проспектору Камнетерке в Альтеракские горы.",
    [7142] = "Отправляйтесь в Альтеракскую долину и убейте генерала дворфов, Вандара Грозовую Вершину. После этого возвращайтесь к Вогге Смертной Хватке в Альтеракские горы.",
    [7161] = "Отправляйтесь в пещеры Дикой Лапы, расположенные на юго-востоке от основной базы в Альтеракской долине, и добудьте вымпел клана Северного Волка. Отнесите выпмел клана Северного Волка воеводе Лаггронду.",
    [7162] = "Отправляйтесь в Пещеру Ледяного Крыла, которые расположены в Альтеракской долине, на юго-западе от Дун Болдара, и добудьте вымпел Грозовой Вершины. Отдайте вымпел лейтенанту Мурпу в Альтеракских горах.",
    [7181] = "Согласно легенде, вождь могущественного племени троллей Секиры Зимы периодически появляется на поле боя, внося хаос и опустошение в жизнь обитателей Альтеракской долины. Если Коррак появится, убейте его и возвращайтесь к воеводе Лаггронду.",
    [7201] = "Отправляйтесь в Глубины Черной горы и добудьте 10 мер сущности Стихий. Стоит начать поиски с големов и их создателей. Вивиан Лаграв также бормотала что-то про элементалей.",
    [7202] = "Согласно легенде, вождь могущественного племени троллей Секиры Зимы периодически появляется на поле боя, внося хаос и опустошение в жизнь обитателей Альтеракской долины. Если вам удастся найти Коррака, убейте его и возвращайтесь к лейтенанту Мурпу в Альтеракские горы.",
    [7223] = "Принесите 20 обломков брони Марготу Подземной Кузне в Дун Болдар.",
    [7224] = "Принесите 20 обломков брони кузнецу Регзару в деревню Северного Волка.",
    [7241] = "Отправляйтесь в Альтеракскую долину, расположенную в Альтеракских горах. Найдите воеводу Лаггронда у входа в тоннель и поговорите с ним, чтобы начать свою военную карьеру в клане Северного Волка. Альтеракская долина находится к северу от деревни Мельница Таррен у подножия Альтеракских гор.",
    [7261] = "Отправляйтесь в Альтеракскую долину, к предгорьям Хилсбрада. Найдите лейтенанта Мурпа рядом со входом в туннель и поговорите с ним. Во славу Бронзеборода!",
    [7281] = "Отправляйтесь на территорию Грозовой Вершины и убейте командира Карла Филипса. После выполнения задания возвращайтесь к командиру Луи Филипсу.",
    [7282] = "Отправляйтесь на территорию клана Северного Волка и убейте командира Луи Филипса. После выполнения задания возвращайтесь к командиру Карлу Филипсу.",
    [7301] = "Отправляйтесь в крепость Северного Волка и поищите командиров звена Слидора, Змейера и Ичмана. Вернитесь с отчетом к командиру Даффи.",
    [7302] = "Выясните, что стало с командирами звена Гусом, Джезтором и Малвериком. Вернитесь с отчетом к командиру Мулфорту.",
    [7321] = "Принесите 10 кусков черепашьего мяса и немного смягчающих пряностей Кристофу Френчу на Мельницу Таррен.",
    [7361] = "Вам поручили убивать в Альтеракской долине ночных эльфов. Убив ночного эльфа, вернитесь с его отрубленной головой к Нажьяку Проклятуну в крепость Северного Волка.",
    [7362] = "Убивайте гномов в Альтеракской долине. Убив гнома, принесите Раваку Зловещему Тотему в крепость Северного Волка пучок волос гнома.",
    [7363] = "Вам поручили убивать людей в Альтеракской долине. Убив человека, принесите командору Луи Филипсу (который бродит между линией фронта и крепостью Северного Волка) осколок человеческой кости. Окончить человеческие страдания совсем несложно!",
    [7366] = "Ваше задание – убивать в Альтеракской долине Отрекшихся. Убейте Отрекшегося и возвращайтесь к Карлу Филипсу (он ходит между лесопилкой и рудником) с сердцем Отрекшегося.",
    [7381] = "В случае, если Коррак Кровопуск возвратится на Поле брани, найдите его и уничтожьте. Принесите череп Коррака воеводе Лаггронду в предгорья Хилсбрада.",
    [7382] = "В случае, если Коррак Кровопуск возвратится на Поле брани, найдите его и уничтожьте. Принесите череп Коррака лейтенанту Хаггердину в предгорья Хилсбрада.",
    [7383] = "Наполните аметистовый фиал и принесите его Коритрасу Лунному Гневу в Доланаар.",
    [7441] = "Отправляйтесь в Забытый Город и отыщите беса Пузиллина. Любыми доступными средствами убедите Пузиллина отдать вам книгу заклинаний Аж'Тордина. Если добудете книгу, вернитесь к Аж'Тордину в павильон Лорисс в Фераласе.",
    [7461] = "Перебейте стражей, которые охраняют 5 столпов, снабжающих энергией Тюрьму Бессмер'тера. После того как столпы угаснут, силовое поле, удерживающее Бессмер'тера, рассеется. Войдите в Тюрьму Бессмер'тера и уничтожьте злого демона, который находится внутри. И, наконец, сразитесь с принцем Тортелдрином в Читальне. Если задание будет выполнено успешно, вернитесь во двор, к прародительнице Шен'дралар.",
    [7463] = "Ступайте в Квартал Криводревов Забытого Города и убейте элементаля воды Гидротварь. Вернитесь в Читальню к сказителю Лидросу и принесите ему сущность Гидротвари.",
    [7481] = "Отыщите в Забытом Городе Тельмия Сновидца. Вернитесь в лагерь Мохаче к ведуну Королуску и сообщите ему все, что вам удалось узнать.",
    [7482] = "Отыщите в Забытом Городе Тельмия Сновидца. Вернитесь в крепость Оперенной Луны к исследовательнице Рунический Шип и сообщите ей все, что вам удалось узнать.",
    [7483] = "Принесите сказителю Лидросу в Забытом Городе \"Манускрипт Скорости\", 1 безупречный черный алмаз, 2 больших сияющих осколка и 2 образца крови героев, чтобы получить магический камень стремительности.",
    [7484] = "Принесите сказителю Лидросу в Забытом Городе \"Манускрипт Средоточия\", 1 безупречный черный алмаз, 4 больших сияющих осколка и 2 образца шкуры Тени, чтобы получить магический камень сосредоточения.",
    [7485] = "Принесите сказителю Лидросу в Забытом Городе \"Манускрипт Защиты\", 1 безупречный черный алмаз, 2 больших сияющих осколка и 1 потертый шовный материал поганища, чтобы получить магический камень защиты.",
    [7486] = "Заберите свою награду из сундука Гидраксиса.",
    [7488] = "Принесите сеть Лефтендрис Латроникусу Лунному Копью в Крепость Оперенной Луны в Фераласе.",
    [7489] = "Принесите сеть Лефтендрис Тало Терновому Копыту в Лагере Мохаче в Фераласе.",
    [7490] = "Отнесите голову Ониксии Траллу в Оргриммар.",
    [7491] = "Найдите властителя Рунтака в Аллее Силы.",
    [7492] = "Поговорите с Тало Терновым Копытом в Лагере Мохаче в Фераласе.",
    [7494] = "Поговорите с Латроникусом Лунным Копьем в Крепости Оперенной Луны в Фераласе.",
    [7495] = "Отнесите голову Ониксии Верховному лорду Болвару Фордрагону в Штормград.",
    [7496] = "Найдите майора Маттингли в Аллее Героев.",
    [7498] = "Верните книгу законным владельцам.",
    [7499] = "Верните книгу законным владельцам.",
    [7500] = "Верните книгу законным владельцам.",
    [7501] = "Верните книгу законным владельцам.",
    [7502] = "Верните книгу законным владельцам.",
    [7503] = "Верните книгу законным владельцам.",
    [7504] = "Верните книгу законным владельцам.",
    [7505] = "Верните книгу законным владельцам.",
    [7506] = "Верните книгу законным владельцам.",
    [7507] = "Верните \"Справочник Ностро по убийству драконов\" в Читальню.",
    [7508] = "Отдайте тусклый и плоский эльфийский клинок сказителю Лидросу.",
    [7509] = "Заставьте Ониксию дохнуть своим огненным дыханием на потускневший древний клинок. После этого схватите раскаленный древний клинок. Имейте в виду, что раскаленным он останется ненадолго, так что медлить не следует! Последнее, что нужно сделать – это убить драконицу и вонзить раскаленный древний клинок в ее труп. Сделайте это – и Кель-Серрар навеки станет вашим!",
    [7562] = "Поговорите с Мор'зулом Кровопуском в Пылающих степях.",
    [7563] = "Принесите 30 бутылок крови яростных зверей Мор'зулу Кровопуску в Пылающие степи.",
    [7564] = "Принесите ларец Крови Горзиеки Дикоглазу в Пылающие степи.",
    [7581] = "Отправляйтесь в Забытый Город, что в Фераласе и добудьте 15 порций крови сатиров из племени Исчадий Природы, что живут в Квартале Криводревов. Вернитесь к Дайо из Гниющего шрама по выполнении поручения.",
    [7582] = "Отправляйтесь к Теснине Зловещего Шепота в Зимних ключах и добудьте 5 слез Хедерины у демонов Хедерины, что населяют эту теснину. Вернитесь к Дайо из Гниющего шрама по выполнении поручения.",
    [7583] = "Отправляйтесь в Гниющий шрам и и найдите командира стражников ужаса. При помощи светящегося кристалла заточения поймайте командира стражников ужаса. Будьте готовы к отчаянным атакам и сопротивлению, поскольку демон будет пытаться избежать заточения. Если вы добьетесь успеха, отнесите пленного стражника ужаса Дайо в Гниющий шрам.",
    [7601] = "Поговорите с Бесенком в Оскверненном лесу.",
    [7602] = "Бесенок из Оскверненного леса просит вас принести ему три порции безупречной субстанции скверны из трех различных мест. Безупречной субстанцией в Азшаре владеют сатиры из племени Легаши. В Джеденаре она есть у джеженарских легионеров. Стражи Скверны в Выжженных землях владеют этой субстанцией в своих краях. Добудьте три типа безупречной субстанции Скверны и возвращайтесь к Бесенку в Оскверненный лес.",
    [7603] = "Обыщите долину Рваных Ран в Оскверненном лесу и найдите останки Крошиуса. Когда вы их найдете, поднесите к ним пламень Скверны и подождать, пока Крошиус не восстанет из праха. Когда инфернал очнется, убейте его и возьмите из его тела огненное ядро Крошиуса. Принесите огненное ядро Крошиуса Ниби Всемогущему в Оскверненный лес.",
    [7604] = "Подпишите договор с представителем братства Тория Локтосом Недобрым Торговцем, если вам нужен чертеж сульфуронского молота.",
    [7622] = "Спасите жизни 50 крестьян прежде, чем 15 из них будут убиты. Поговорите с Эрис Тайнопламень по выполнению задания. Число убитых крестьян можно узнать из почты Смерти.",
    [7623] = "Купите зелья Теней у Горзиеки в Пылающих степях. Приняв зелья, пройдите в Джеденар и поговорите с лордом Гиблопустом.",
    [7624] = "Сразитесь с Улатеком и принесите сердце предателя лорду Гиблопусту в Джеденар.",
    [7625] = "Купите зоротианскую звездную пыль у Ур'Дана. Отнесите ее Горзиеки Дикоглазу в Пылающие степи.",
    [7626] = "Отнесите 10 эликсиров Силы Теней Горзиеки Дикоглазу в Пылающие степи.",
    [7627] = "Отнесите 6 больших блестящих осколка и 25 кусков руды черного железа Дикоглазу в Пылающие степи.",
    [7628] = "Принесите 35 шкур черного дракона Горзиеки Дикоглазу в Пылающие степи.",
    [7629] = "Отнесите беса в бутылке в алхимическую лабораторию Некроситета. После создания пергамента верните бутылку Горзиеки Дикоглазу.",
    [7630] = "Принесите 3 арканитовых слитка Горзиеки в Пылающие степи.",
    [7631] = "Прочтите инструкции Мор'зула. Призовите ксоротианского коня погибели, одолейте его и подчините его дух.",
    [7632] = "Найдите хозяина древнего окаменелого древесного листа. Удачи, <имя>, мир велик.",
    [7634] = "Хастат Древний просит вас принести ему жилу взрослого синего дракона. По выполнении задания возвращайтесь к Хастату в Оскверненный лес.",
    [7635] = "Стома Древний просит вас принести ему жилу взрослого черного дракона. Добыв жилу, возвращайтесь к Стоме в Оскверненный лес.",
    [7636] = "Вы должны найти и уничтожить следующих четверых демонических разносчиков порчи : Симон Совратительницу. Клинфрана Безумного. Соленора Убийцу. Арториуса Судьбоносного. Уничтожьте этих тварей и возвращайтесь к Вартусу Древнему в Оскверненный лес с их головами. В поисках местонахождения этих демонов сверяйтесь с окаменевшей корой. Вы ОБЯЗАНЫ выполнить это задание в одиночку.",
    [7637] = "Доберитесь до Стальгорна и получите курильницу экзорцизма у Верховного жреца Рохана. За курильницу нужно будет внести плату в размере 150 золотых монет.",
    [7638] = "Поговорите с лордом Грейсоном Тенеломом в Храмовом квартале Штормграда.",
    [7639] = "Принесите курильницу экзорцизма лорду Грейсону Тенелому в Храмовый квартал Штормграда.",
    [7640] = "Используйте курильницу экзорцизма для вызова из-под земли призраков, мучающих Долину Ужаса. Когда убьете 25 духов долины Ужаса, вернитесь к лорду Грейсону Тенелому в Храмовый квартал Штормграда.",
    [7641] = "Поговорите с Гримандом Элмором в Квартале Дворфов Штормграда.",
    [7642] = "Принесите Гриманду Элмору в Квартал Дворфов Штормграда 40 отрезов рунной ткани, 6 арканитовых слитков, 10 цветков слезы Артаса, 5 сосудов со святой водой Стратхольма и 150 золотых монет.",
    [7643] = "Купите лошадиный корм для Духа древнего коня у Меридет Карлсон в Южнобережье. Убейте Тендриса Криводрева в башне Забытого Города в Фераласе и освободите духа. Накормите духа кормом и получите благословление для арканитового чепрака.",
    [7644] = "Вернитесь вместе с благословенным арканитовым чепраком к лорду Грейсону Тенелому в Храмовый квартал Штормграда.",
    [7645] = "Принесите 20 витаминизированных печений из манны – ключевых составляющих обогащенного манной лошадиного корма – Меридет Карлсон в Южнобережье в предгорьях Хилсбрада. Продаются они только в Серебряном Рассвете. Кроме того, понадобится дать ей 50 золотых, чтобы успокоить ее ущемленное самолюбие.",
    [7646] = "Принесите азеротский алмаз и безупречный черный алмаз лорду Грейсону Тенелому в Храмовый квартал Штормграда.",
    [7647] = "Используйте магический кристалл в центре подвала Главного склепа в Некроситете. Победите вызванных духов, а затем – рыцаря смерти Темного Терзателя, который появится после поражения духов. Верните падшему скакуну Темного Терзателя его спасенную душу и покройте его благословенным зачарованным чепраком.",
    [7648] = "Покажите арканитовый чепрак лорду Грейсону Тенелому в Храмовом квартале Штормграда.",
    [7649] = "Верните книгу законным владельцам.",
    [7650] = "Верните книгу законным владельцам.",
    [7651] = "Верните книгу законным владельцам.",
    [7667] = "Принесите Сагорну Гребнестраннику в Аллею Мудрости в Оргриммаре азеротский алмаз и безупречный черный алмаз.",
    [7670] = "Поговорите с лордом Грейсоном Тенеломом в Храмовом квартале Штормграда.",
    [7701] = "Дворф Черного Железа, вероломный надзиратель Мальториус, скрывается в глубине Шлаковой Ямы в Котле, что в Тлеющем ущелье. Убейте надзирателя Мальториуса и принесите его голову дозорному капитану Лоло Долгобою.",
    [7703] = "Добудьте латную рукавицу Мощи Гордока и вернитесь с ней к капитану Давигрому в Забытом Городе. По словам Давигрома, в \"старых байках\" говорится, что Тортелдрин – \"страшный эльф\", называющий себя принцем, – похитил эту рукавицу у одного из королей Гордоков.",
    [7721] = "Соберите 10 ядер элементалей воды, убивая морских элементалей и морских валов на Забытом берегу в Фераласе, и принесите их Зорбину Дребезгуну, который находится неподалеку от порта.",
    [7722] = "Верните секретные документы по изготовлению огненного плавня, украденные надзирателем Мальториусом. Инспектор скорее всего находится в Шлаковой Яме в Котле. Документы верните мастеру-кузнецу Гориврату в Тлеющем ущелье.",
    [7723] = "По поручению Хансела Большерука убейте 20 тяжелых боевых големов, которых можно найти в землях, окружающих Котел в Тлеющем ущелье. По выполнении задания вернитесь к Ханселу.",
    [7724] = "По указанию Хансела Большерука убейте 20 |4опаляющего лавового паука:опаляющих лавовых пауков:опаляющих лавовых пауков; в Тлеющем ущелье. Пауки водятся на вулканических плато и в озерах лавы в Тлеющем ущелье. Когда убьете достаточно пауков, вернитесь к Ханселу в Тлеющее ущелье.",
    [7725] = "Используйте ультрасжиматель Зорбина, чтобы уменьшить великанов любого вида, каких вы найдете в Фераласе. Принесите 10 остатков миниатюризации этих великанов Зорбину Дребезгуну в порт Забытого берега в Фераласе.",
    [7726] = "Соберите 6 ядер элементалей воды, убивая морских элементалей и морских валов на Забытом берегу в Фераласе, и принесите их Зорбину Дребезгуну, который находится неподалеку от порта.",
    [7727] = "По поручению Хансела Большерука убейте 20 пламезавров, обитающих в озерах лавы в Шлаковой Яме - это часть Котла в Тлеющем ущелье. По выполнении задания вернитесь к Ханселу в Тлеющее ущелье.",
    [7728] = "Найдите и верните фурму и подзорную трубу наблюдателя надсмотрщику Скренджу в Тлеющем ущелье. Единственная известная информация: вещи были украдены дворфами Черного Железа. Подзорная труба является бесценным прибором для наблюдения, а фурма – незаменимым кузнечным инструментом.",
    [7729] = "Убейте 15 надсмотрщиков и 15 поработителей из клана Черного Железа. По выполнении задания вернитесь к десятнику Скренджу в Тлеющее ущелье.",
    [7730] = "Принесите 20 панцирей Цуккаш Хадокену Быстрому Страннику в Лагерь Мохаче в Фераласе.",
    [7731] = "Убейте жалохвоста в Гудящей Бездне и принести железы ядохлеста Хадокену Быстрому Страннику в Лагерь Мохаче в Фераласе.",
    [7732] = "Доставьте отчет о нашествии насекомых-Цуккаш на Лагерь Мохаче Зилзибину Барабанному Бою, который проживает на Волоке в Оргриммаре.",
    [7733] = "Принесите 10 шкур йети из пещеры Бешеного оврага Пратту Макгруббену в Крепость Оперенной Луны в Фераласе.",
    [7734] = "Принесите 10 шкур йети из пещеры Бешеного оврага Джангору Быстрому Страннику в Лагерь Мохаче в Фераласе.",
    [7735] = "Отнесите безупречную шкуру йети Пратту Макгруббену в Крепость Оперенной Луны в Фераласе.",
    [7738] = "Отнесите безупречную шкуру йети Джангору Быстрому Страннику в Лагерь Мохаче в Фераласе.",
    [7761] = "Вот уж действительно идиот... Похоже, вам нужно найти это клеймо и выжечь на руке метку Драккисата, чтобы получить доступ к сфере Приказа. В письме ясно сказано, что генерал Драккисат охраняет клеймо. Наверное, стоит проверить.",
    [7781] = "Отнесите голову Нефариана Верховному лорду Болвару Фордрагону в Штормград.",
    [7782] = "Поговорите с фельдмаршалом Афрасиаби в Аллее Героев рядом со Штормградом.",
    [7783] = "Отнесите голову Нефариана Траллу в Оргриммар.",
    [7784] = "Поговори с верховным воеводой Саурфангом. Он ждет тебя на аллее Силы в Оргриммаре.",
    [7785] = "Изучите Сосуд Возрождения и вернитесь к верховному лорду Демитриану.",
    [7786] = "Чтобы освободить Громораана Ветроносца из тюрьмы, отнесите правый и левый наручник Ветроносца, 10 слитков элементия и сущность Повелителя огня верховному лорду Демитриану.",
    [7787] = "Отдайте Дремлющий клинок Игривого Ветра верховному лорду Демитриану.",
    [7810] = "Поговорите с Коротышкой Джоном Мифрилом на арене Тернистой долины.",
    [7815] = "Убейте 15 морских хрустогрызов по поручению Катума Удильщика из деревни Сломанного Клыка во Внутренних землях.",
    [7816] = "Убейте Гаммериту и верните Катуму Удильщику из деревни Сломанного Клыка его лучшую блесну. Катум сказал, что Гаммерита ползает по берегу среди остальных черепах.",
    [7828] = "Убейте 15 среброгривых бродяг и 15 среброгривых ревунов по поручению охотника Мархора из деревни Сломанного Клыка во Внутренних землях. Мархор сказал, что волки обирают в лесах Внутренних земель.",
    [7829] = "Убейте 20 диких совухов по поручению охотника Мархора из деревни Сломанного Клыка во Внутренних землях. Мархор сказал, что совухи обитают в лесах Внутренних земель.",
    [7830] = "Убейте остроклюва-повелителя небес и принесите его перо охотнику Мархору в деревню Сломанного Клыка. Мархор говорил, что остроклюв водятся во Внутренних землях.",
    [7839] = "Найдите потерянные инструменты кузнеца Углежога из деревни Сломанного Клыка во Внутренних землях. Углежог сказал, что инструменты могут быть в одном из храмов троллей Порочной Ветви в северо-восточной части Внутренних земель. Также следует проверить на Осклизлой скале.",
    [7840] = "Найдите обед Лярда из деревни Сломанного Клыка во Внутренних землях. Лярд сказал, что потерял свой обед на острове к северу, где могут встретиться тролли из клана Порочной Ветви.",
    [7841] = "Убейте 15 гонцов, 15 разведчиков, 15 стрелков и 15 разведчиков Высокодолья по поручению Отхо Можи'ко из деревни Сломанного Клыка. Ночных эльфов из Высокодолья можно найти в Сторожке Кель'Данил в северо-западной части Внутренних земель.",
    [7842] = "Принесите 10 длинных элегантных перьев Отхо Можи'ко из деревни Сломанного Клыка во Внутренних землях. Перья нужно собрать с местных грифонов, которых можно найти практически в любом месте Внутренних земель.",
    [7843] = "Заберитесь на Заоблачный пик в западной части Внутренних Земель и оставьте возле колодца в центре города последнее предупреждение для Громового Молота. После выполнения задания возвращайтесь к Отхо Можи'ко в деревню Сломанного Клыка. Берегитесь дворфов Громового Молота и других сторонников Альянса.",
    [7844] = "Убейте 30 охотников за скальпами и 15 ворожеев из племени Порочной Ветви по поручению Яо'джин из деревни Сломанного Клыка. Яо'джин сказала, что эти тролли живут близ храмов Шаол-Вата и Агол-Вата в северо-восточной части Внутренних земель.",
    [7845] = "Спасите старейшину Сломанного Клыка из Джинта'Алора по поручению его жены из деревни Сломанного Клыка. Старейшину держат в плену на самом верху Джинта'Алор – главного поселения троллей из клана Порочной Ветви, расположенного на юге Внутренних земель.",
    [7846] = "Убейте хранительницу Хита'йю и заберите у нее ключ от оков, после чего возвращайтесь к старейшине Сломанному Клыку в Джинта'Алор и освободите его.",
    [7847] = "Возвращайтесь к старейшине Сломанному Клыку и сообщите ей, что ее муж спасен.",
    [7848] = "Отправляйтесь через портал, ведущий к Огненным Недрам в Глубинах Черной горы и добудьте фрагмент ядра. Принесите его Лотосу Хранителю Портала к Черной горе.",
    [7849] = "Принесите охотнику Мархору из деревни Сломанного Клыка во Внутренних землях кости и череп его брата-близнеца. Мархор сказал, что останки его брата бросили на съедение слизнюкам и волкам Порочной Ветви – все эти твари водятся неподалеку от вершины Джинта'Алор: слизнюки в компостной яме, а волки – в логове.",
    [7850] = "Принесите 10 сосудов с порченой кровью старейшине племени Сломанного Клыка во Внутренние земли. Сосуды с кровью находятся в поселении Джинта'Алор.",
    [7861] = "Убейте коварную жрицу Ведьмису и 20 стражей Аман'заси из клана Порочной Ветви, после чего доложите старейшине племени Сломанного Клыка в Деревне Сломанного Клыка. Коварную жрицу Ведьмису и стражей Аман'заси можно найти в верхней части Джинта'Алора во Внутренних землях.",
    [7862] = "Убейте 20 берсерков, 20 темных охотников, 20 кровопийц и 20 пожирателей душ из племени Порочной Ветви. После выполнения задания вернуться к старейшине Сломанному Клыку во Внутренних землях.",
    [7877] = "Вернитесь в Читальню и найдите сокровище Шен'дралар. Получите свою награду!",
    [7907] = "Принесите колоду Зверей на ярмарку Новолуния.",
    [7927] = "Принесите карты Порталов на ярмарку Новолуния.",
    [7928] = "Принесите карты воинов на ярмарку Новолуния.",
    [7929] = "Принесите колоду Элементалей на ярмарку Новолуния.",
    [8053] = "Принесите Джин'року Разрушителю изначальные поручья Хаккари. Кроме того, вам необходимо заслужить как минимум дружелюбное отношение племени Зандалар. Джин'рок Разрушитель живет на острове Йоджамба, в Тернистой долине.",
    [8054] = "Принесите Джин'року Разрушителю изначальную лацерну Хаккари. Кроме того, вам необходимо заслужить как минимум уважительное отношение племени Зандалар. Джин'рок Разрушитель живет на острове Йоджамба, в Тернистой долине.",
    [8055] = "Принесите Джин'року Разрушителю Изначальную гербовую накидку Хаккари. Кроме того, вам необходимо заслужить как минимум почтительное отношение племени Зандалар. Джин'рок Разрушитель живет на острове Йоджамба, в Тернистой долине.",
    [8056] = "Принесите Майвики Зулдазарской Изначальные обручья Хаккари. Кроме того, вам необходимо заслужить как минимум дружелюбное отношение племени Зандалар. Майвики Зулдазарская живет на острове Йоджамба, в Тернистой долине.",
    [8057] = "Принесите Майвики Зулдазарской изначальный браслет Хаккари. Кроме того, вам необходимо заслужить как минимум дружественное отношение племени Зандалар. Майвики Зулдазарская находится на острове Йоджамба, в Тернистой долине.",
    [8058] = "Принесите Джин'року Разрушителю изначальные обручья Хаккари. Кроме того, вам необходимо заслужить как минимум дружелюбное отношение племени Зандалар. Джин'рок Разрушитель живет на острове Йоджамба, в Тернистой долине.",
    [8059] = "Принесите Джин'року Разрушителю изначальные обручья Хаккари. Кроме того, вам необходимо заслужить как минимум дружелюбное отношение племени Зандалар. Джин'рок Разрушитель живет на острове Йоджамба, в Тернистой долине.",
    [8060] = "Принесите Джин'року Разрушителю изначальные обручья Хаккари. Кроме того, вам необходимо заслужить как минимум дружелюбное отношение племени Зандалар. Джин'рок Разрушитель живет на острове Йоджамба, в Тернистой долине.",
    [8061] = "Принесите Джин'року Разрушителю изначальные обручья Хаккари. Кроме того, вам необходимо заслужить как минимум дружелюбное отношение племени Зандалар. Джин'рок Разрушитель живет на острове Йоджамба, в Тернистой долине.",
    [8062] = "Принесите Фальтиру Слепому из Зул'Гуруба изначальные наручники Хаккари. Кроме того, вам необходимо заслужить как минимум дружественное отношение племени Зандалар. Фальтир Слепой живет на острове Йоджамба, в Тернистой долине.",
    [8063] = "Принесите Фальтиру Слепому изначальные обручья Хаккари. Кроме того, вам необходимо заслужить как минимум дружелюбное отношение племени Зандалар. Фальтир Слепой живет на острове Йоджамба, в Тернистой долине.",
    [8064] = "Принесите Майвики Зулдазарской изначальный кушак Хаккари. Майвики Зулдазарская находится на острове Йоджамба, в Тернистой долине. Кроме того, вам необходимо заслужить как минимум уважительное отношение племени Зандалар.",
    [8065] = "Принесите Майвики Зулдазарской Изначальную гербовую накидку Хаккари. Майвики Зулдазарская находится на острове Йоджамба, в Тернистой долине.",
    [8066] = "Принесите Фальтиру Слепому из Зул'Гуруба изначальную лацерну Хаккари. Кроме того, вам необходимо заслужить как минимум уважительное отношение племени Зандалар. Фальтир Слепой живет на острове Йоджамба, в Тернистой долине.",
    [8067] = "Принесите Фальтиру Слепому из Зул'Гуруба изначальную эгиду Хаккари. Кроме того, вам необходимо заслужить как минимум почтительное отношение племени Зандалар. Фальтир Слепой живет на острове Йоджамба, в Тернистой долине.",
    [8068] = "Принесите Ал'табиму Всевидящему изначальную лацерну Хаккари. Кроме того, вам необходимо заслужить как минимум уважительное отношение племени Зандалар. Альтабим Всевидящий живет на острове Йоджамба, в Тернистой долине.",
    [8069] = "Принесите Ал'табиму Всевидящему изначальную рубашку Хаккари. Кроме того, вам необходимо заслужить как минимум почтительное отношение племени Зандалар. Альтабим Всевидящий живет на острове Йоджамба, в Тернистой долине.",
    [8070] = "Принесите Ал'табиму Всевидящему изначальный кушак Хаккари. Кроме того, вам необходимо заслужить как минимум уважительное отношение племени Зандалар. Ал'табим Всевидящий живет на острове Йоджамба, в Тернистой долине.",
    [8071] = "Принесите Ал'табиму Всевидящему изначальную эгиду Хаккари. Кроме того, вам необходимо заслужить как минимум почтительное отношение племени Зандалар. Ал'табим Всевидящий живет на острове Йоджамба, в Тернистой долине.",
    [8072] = "Принесите Фальтиру Слепому изначальный ремень Хаккари. Кроме того, вам необходимо заслужить как минимум уважительное отношение племени Зандалар. Фальтир Слепой живет на острове Йоджамба, в Тернистой долине.",
    [8073] = "Принесите Фальтиру Слепому из Зул-Гуруба изначальную эгиду Хаккари. Кроме того, вам необходимо заслужить как минимум почтительное отношение племени Зандалар. Фальтир Слепой живет на острове Йоджамба, в Тернистой долине.",
    [8074] = "Принесите Майвики Зулдазарской изначальный ремень Хаккари. Кроме того, вам необходимо заслужить как минимум уважительное отношение племени Зандалар. Майвики Зулдазарская находится на острове Йоджамба, в Тернистой долине.",
    [8075] = "Принесите Майвики Зулдазарской изначальную гербовую накидку Хаккари. Кроме того, вам необходимо заслужить как минимум почтительное отношение племени Зандалар. Майвики Зулдазарская находится на острове Йоджамба, в Тернистой долине.",
    [8076] = "Принесите Ал'табиму Всевидящему изначальный кушак Хаккари. Кроме того, вам необходимо заслужить как минимум уважительное отношение племени Зандалар. Ал'табим Всевидящий живет на острове Йоджамба, в Тернистой долине.",
    [8077] = "Принесите Ал'табиму Всевидящему изначальную рубашку Хаккари. Кроме того, вам необходимо заслужить как минимум почтительное отношение племени Зандалар. Ал'табим Всевидящий живет на острове Йоджамба, в Тернистой долине.",
    [8078] = "Принесите Джин'року Разрушителю изначальный ремень Хаккари. Кроме того, вам необходимо заслужить как минимум уважительное отношение племени Зандалар. Джин'рок Разрушитель живет на острове Йоджамба, в Тернистой долине.",
    [8079] = "Принесите Джин'року Разрушителю изначальную рубашку Хаккари. Кроме того, вам необходимо заслужить как минимум почтительное отношение племени Зандалар. Джин'рок Разрушитель живет на острове Йоджамба, в Тернистой долине.",
    [8105] = "Нападите на рудник, лесопилку, кузницу и ферму и возвращайтесь к фельдмаршалу Освету в Опорный пункт.",
    [8114] = "Отправляйтесь в Низину Арати, захватите и удержите контроль над четырьмя базами одновременно, затем возвращайтесь к фельдмаршалу Освету в Опорный пункт.",
    [8115] = "Возьмите под контроль одновременно все 5 баз в Низине Арати, а затем возвращайтесь к фельдмаршалу Освету в Опорный пункт.",
    [8120] = "Нападите на рудник, лесопилку, кузницу и стойла в Низине Арати и возвращайтесь к повелительнице смерти Двайр в Павший Молот.",
