    [8728] = "Нарайн Причуддень и Танариса хочет, чтобы вы принесли ему 20 арканитовых слитков, 10 кусков элементиевой руды, 10 азеротских бриллиантов и 10 синих сапфиров.",
    [8729] = "Забросье арканитовый буй в Водоворот в Штормовой бухте Азшары.",
    [8730] = "Убейте Нефариана и добудьте осколок красного скипетра. Верните осколок красного скипетра Анахроносу в Пещеры Времени в Танарис. На выполнение задания у вас есть 5 часов.",
    [8731] = "Поступите в распоряжение легиона Оргриммара возле улья Регал. Подготовьте неподписанные бумаги о полевых обязанностях и получите подписанные бумаги о полевых обязанностях, отнесите их Зовущему Калдону в крепость Кенария. Внимание: исцеление или наложение благоприятных заклинаний на бойцов легиона Оргриммара переводит в режим PvP.",
    [8733] = "Отправляйтесь на континент Тельдрассил и найдите агента Малфуриона у стен Дарнасса.",
    [8734] = "Отправляйтесь в Лунную поляну и поговорите с хранителем Ремулосом.",
    [8735] = "Отправьтесь к четырем порталам сна Азерота и добудьте фрагменты порчи Кошмара из каждого из них. Вернитесь к хранителю Ремулосу на Лунную поляну по завершении задания.",
    [8736] = "Защитите Ночную гавань от Эраникуса. Не дайте погибнуть хранителю Ремулосу. Не убивайте Эраникуса. Защищайте себя. Дождитесь Тиранды.",
    [8737] = "Призовите и убейте лазурного храмовника и доложите о выполнении задания Бору Буйногривому из крепости Кенария. Для завершения задания принесите тактическую задачу I.",
    [8738] = "Свяжитесь с разведчиком Кенария Ландионом в улье Регал и отнесите донесение разведчика из улья Регал Зовущей из клана Гордый Рог в крепость Кенария. Кроме того, принесите тактическую задачу VII.",
    [8739] = "Свяжитесь с разведчиком Кенария Джалией в улье Аши и отнесите донесение разведчика Зовущей из клана Гордый Рог в крепость Кенария. Кроме того, принесите тактическую задачу VIII.",
    [8740] = "Убейте сумеречного мародера Морну и 5 сумеречных мародеров. Доложите о выполнении задания Зовущей из клана Гордый Рог. Кроме того, сдайте тактическую задачу IX.",
    [8741] = "Отнесите осколок зеленого скипетра Анахроносу в Пещеры Времени в Танарисе.",
    [8770] = "Убейте 30 защитников из улья Аши и доложите о выполнении задания командиру Мар'алиту в крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу I.",
    [8771] = "Убейте 30 пескоходов из улья Аши и доложите о выполнении задания командиру Мар'алиту в крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу II.",
