    [97986] = "Поговорите с лекарем в лагере Серебряного Рассвета на северо-западе от озера Чернолесья в Восточных Чумных землях.",
    [97987] = "Поговорите с Саэрой Вирравэй в парке Штормграда.",
    [98013] = "Убейте 12 |4мирмидона:мирмидонов:мирмидонов;, 8 |4колдунью:колдуний:колдуний; и 6 |4воина:воинов:воинов; из клана Гремучей чешуи по просьбе Арбала из Рощи Древних.",
    [98021] = "Поговорите с Грианом Камнегривом в Западном крае.",
    [98024] = "Поговорите с Тхорком в Перекрестке, что в Степях.",
    [98025] = "Найдите и убейте сову Джай'ванель и добудьте одно из ее перьев. Эту черную сову видели к северу от руин Амет'Арана у подножия горы. Доложите о смерти Джай'ванель часовому Глинде Нал'Шии в Аубердине.",
    [98027] = "Отнесите ожерелье с полумесяцем Майлинн в Астранаар.",
    [98028] = "Принесите помутневшую водяную сферу Ону в Рощу Древних на Темных берегах.",
    [98042] = "Добудьте несравненное око у сумеречного послушника или сумеречного лиходея у Меча Властителя на Темных берегах и найдите в Аубердине того, кто заберет его у вас.",
    [98046] = "Принесите опустошенный сосуд Ларии в храм Луны в Дарнассе.",
    [98059] = "Положите запечатанный заказ компании, который вам дали, на стол для учета в ратуше Хилсбрада.",
    [98065] = "Принесите частицы Лунного колодца Тиранде Шелест Ветра в храм Луны в Дарнассе.",
    [98067] = "Разместите сов-часовых возле входа в глубины крепости Кенария, дарнасского банка, таверны на Террасе Ремесленников и городских ворот по просьбе часового Далии Солнечный Клинок из храма Луны в Дарнасе.",
    [98069] = "Принесите 8 ящиков с украденными припасами Вольного Ветра Джандии на заставу Вольного Ветра.",
    [98070] = "Убейте 5 |4визгливую гарпию:визгливых гарпий:визгливых гарпий;, 5 |4визгливую бродяжницу:визгливых бродяжниц:визгливых бродяжниц; и 5 |4визгливую призывательницу:визгливых призывательниц:визгливых призывательниц; ветров.",
    [98071] = "Отнесите бутылки с фолрукским сортовым вином в Дун Гарок в юго-восточной части предгорий Хилсбрада и принесите назад мешок их домашнего хмеля.",
    [98072] = "Принесите 8 безупречных алых чешуек Джеймсу Халлорану в Гавань Менетилов.",
    [98093] = "Убейте 7 |4грозового ящера:грозовых ящеров:грозовых ящеров; и 7 |4многозубого ловца:многозубых ловцов:многозубых ловцов; вокруг, чтобы Сулхаса смогла спуститься с дерева.",
    [98094] = "Верховный палач Дарталия хочет, чтобы вы доставили новые указания стражу смерти Масоджу на юг от Мельницы Таррен, рядом с Дун Гароком.",
    [98095] = "Страж смерти Масодж хочет, чтобы вы разместили три аптекарских флакона на возвышенностях в предгорьях Хилсбрада и вернулись к нему.",
    [98096] = "Найдите командира Песню Истины на заставе Талрендис в Азшаре и узнайте, где находится Кельдара Солнечный Клинок.",
